// ================= Aprender: módulo «impostos» =================
// Regras de Portugal só com fonte oficial (campo `src`); o que não ficou confirmado leva `pending:true` («Por confirmar»).
// Fontes oficiais consultadas em 17/11/2026: Portal das Finanças (CIRS, EBF, CIS, guia «Tributação de produtos financeiros em sede de IRS» de outubro de 2023,
// Ofício-Circulado n.º 20291 de 17/03/2026, Agenda Fiscal 2026), Lei n.º 31/2024 e Decreto-Lei n.º 97/2026 (PDF no Portal das Finanças).
// Os valores dos escalões do IRS NÃO são escritos aqui (mudam todos os anos).

const _imp_e2=n=>Number(n).toLocaleString('pt-PT',{style:'currency',currency:'EUR'});
const _imp_T=0.28;                                   // taxa especial (art. 72.º CIRS)
const _imp_t=(g,ex)=>g*(1-(ex||0))*_imp_T;           // imposto sobre o ganho g, com a parte `ex` excluída (art. 43.º, n.º 5 CIRS)
const _imp_pc=x=>(x*100).toLocaleString('pt-PT',{maximumFractionDigits:2})+'%';
const _imp_V='verificado em 17/11/2026';
const _imp_L31={l:'Diário da República / AT: Lei n.º 31/2024, de 28 de junho (mercado de capitais)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/legislacao/diplomas_legislativos/Documents/Lei_31_2024.pdf'};
const _imp_43={l:'Portal das Finanças: artigo 43.º do Código do IRS (mais-valias)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs43.aspx'};
const _imp_55={l:'Portal das Finanças: artigo 55.º do Código do IRS (dedução de perdas)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs55.aspx'};
const _imp_10={l:'Portal das Finanças: artigo 10.º do Código do IRS (incrementos patrimoniais)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs10.aspx'};
const _imp_81={l:'Portal das Finanças: artigo 81.º do Código do IRS (dupla tributação internacional)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs81.aspx'};
const _imp_60={l:'Portal das Finanças: artigo 60.º do Código do IRS (prazo de entrega)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs60.aspx'};
const _imp_OF={l:'AT: Ofício-Circulado n.º 20291, de 17/03/2026 (Modelo 3 em vigor a partir de 2026)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/legislacao/instrucoes_administrativas/Documents/Oficio-circulado-20291-2026.pdf'};
const _imp_DL97={l:'Portal das Finanças: Decreto-Lei n.º 97/2026, de 20 de maio (habitação e arrendamento)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/legislacao/diplomas_legislativos/Documents/decreto-lei-97-2026.pdf'};
const _imp_AG={l:'Portal das Finanças: Agenda Fiscal 2026, quadro-resumo das obrigações declarativas',u:'https://info.portaldasfinancas.gov.pt/pt/apoio_contribuinte/calendario_fiscal/Pages/Quadro_res_Decl_2026.aspx'};
const _imp_68={l:'Portal das Finanças: artigo 68.º do Código do IRS (escalões)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs68.aspx'};
const _imp_TGIS={l:'Portal das Finanças: Tabela Geral do Imposto do Selo',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/selo/Pages/ccod-selo-tabgiselo.aspx'};

// Escalões FICTÍCIOS, só para explicar o mecanismo do englobamento (os reais estão no art. 68.º e mudam todos os anos).
const _imp_fic=[[10000,0.10],[30000,0.25],[Infinity,0.40]];
const _imp_prog=r=>{ let t=0,p=0; for(const [lim,tx] of _imp_fic){ if(r>p) t+=(Math.min(r,lim)-p)*tx; p=lim; } return t; };
const _imp_marg=(base,add)=>_imp_prog(base+add)-_imp_prog(base);   // imposto extra de englobar `add` em cima de `base`
// Modelo ilustrativo acumulação vs distribuição (valores de exemplo, sem comissões, custos nem inflação).
const _imp_ad=(anos,g,y)=>{ const P=10000; let V=P,C=P,divTax=0;
  for(let i=0;i<anos;i++){ const d=V*y; divTax+=d*_imp_T; V=V*(1+g-y)+d*(1-_imp_T); C+=d*(1-_imp_T); }
  const sale=Math.max(0,V-C)*_imp_T, A=P*Math.pow(1+g,anos);
  return {P,dist:{V,tax:divTax+sale,net:V-sale},acc:{V:A,tax:(A-P)*_imp_T,net:A-(A-P)*_imp_T},acc30:{V:A,tax:(A-P)*_imp_T*0.7,net:A-(A-P)*_imp_T*0.7}}; };

// Imóveis: valores de exemplo (sem correção monetária).
const _imp_im=(()=>{ const renda=600,rendaAno=renda*12,desp=1800,liq=rendaAno-desp,real=200000,comp=150000,obras=10000,dsp=2000,ganho=real-comp-obras-dsp,cont=ganho*0.5,reinv=100000,excl=ganho*(reinv/real),rest=ganho-excl,contRest=rest*0.5; return {renda,rendaAno,desp,liq,real,comp,obras,dsp,ganho,cont,reinv,excl,rest,contRest}; })();

LRN.push(
{ id:'mais-valias', topic:'impostos', o:1, title:'Mais-valias: quanto imposto pagas ao vender', mins:9,
  lead:'Quando vendes ações ou ETFs por mais do que pagaste, o ganho paga imposto em Portugal: por regra, 28% sobre o saldo positivo do ano, com um desconto que cresce se ficares muito tempo com o investimento. Perceber isto muda a forma como decides quando vender.',
  blocks:[
    {t:'scene',id:'sc',s:'mais',alt:"Um círculo de lucro com uma fatia de 28% a afastar-se: o imposto. Os outros 72% ficam contigo.",cap:"Por cada 100 € de lucro, 28 € vão para o imposto (no caso geral)."},
    {t:'h',id:'h0',x:'Um ganho que só existe quando vendes'},
    {t:'p',id:'p0',x:'Imagina que compras uma bicicleta usada por 100 € e que, com o tempo, ela passa a valer 150 €. Enquanto não a vendes, os 50 € são um ganho «no papel»: podem desaparecer amanhã. Só quando vendes é que o ganho se torna real. Com os investimentos passa-se o mesmo. Uma ação ou um ETF que subiu 40% não paga imposto enquanto estiver na tua conta. O imposto aparece na <b>venda</b>.'},
    {t:'p',id:'p0b',x:'A este ganho chama-se <b>mais-valia</b>; se for uma perda, <b>menos-valia</b>. Para o IRS, são rendimentos da <b>categoria G</b> (incrementos patrimoniais). O Código do IRS diz que a venda de partes sociais e outros valores mobiliários, e o resgate de unidades de participação em fundos de investimento, geram mais-valias. Os ETFs, que são fundos cotados em bolsa, entram aqui.'},
    {t:'h',id:'h1',x:'Como se calcula o ganho, passo a passo'},
    {t:'ul',id:'u0',x:[
      '<b>Valor de venda</b>: o que recebeste (preço por número de unidades).',
      '<b>Valor de compra</b>: o que pagaste pelas unidades que vendeste.',
      '<b>Despesas</b>: o Código permite acrescentar ao custo as despesas necessárias e efetivamente suportadas na compra e na venda (as comissões, por exemplo), com prova documental.',
      '<b>Ganho = venda − compra − despesas.</b> Se der negativo, é uma perda.']},
    {t:'p',id:'p1',x:'Simula uma venda. As comissões abatem ao ganho. Se o saldo do ano for negativo, não há imposto nesse ano.'},
    {t:'w',id:'w1',w:'tax'},
    {t:'stat',id:'st1',v:28,fmt:'pct',label:'taxa especial (autónoma) sobre o saldo anual positivo de mais-valias de ações e ETFs (art. 72.º do Código do IRS)'},
    {t:'h',id:'h2',x:'O saldo do ano: o que realmente é tributado'},
    {t:'p',id:'p2',x:'O imposto não incide sobre cada venda isolada, mas sobre o <b>saldo do ano</b>: somas todos os ganhos e subtrais todas as perdas das vendas de ações e fundos desse ano civil. Só se o resultado for positivo é que há imposto. Podes ler tudo o que se passa com as perdas no tema «Menos-valias: perdas, saldo anual e reporte para anos seguintes».'},
    {t:'p',id:'p2b',x:`Um exemplo com duas vendas no mesmo ano (valores de exemplo, com 15 € de comissões em cada venda): um ETF comprado por ${_imp_e2(5000)} e vendido por ${_imp_e2(6400)}, e uma ação comprada por ${_imp_e2(3000)} e vendida por ${_imp_e2(2500)}. O ETF dá ${_imp_e2(6400-5000-15)} de ganho e a ação dá ${_imp_e2(2500-3000-15)} de perda. O saldo do ano é ${_imp_e2(6400-5000-15+2500-3000-15)}, e o imposto a 28% é ${_imp_e2((6400-5000-15+2500-3000-15)*0.28)}. A perda da ação reduziu a base de imposto do ETF.`},
    {t:'h',id:'h3',x:'Quanto mais tempo, menos imposto: a regra de 2024'},
    {t:'p',id:'p3',x:`Desde 29 de junho de 2024 (Lei n.º 31/2024), o artigo 43.º do Código do IRS prevê que, para <b>valores mobiliários admitidos à negociação</b> (ações e ETFs cotados) ou <b>partes de fundos abertos</b>, uma parte do saldo fica fora do imposto, consoante o tempo que ficaste com o ativo: 10% se o detiveste mais de 2 anos e menos de 5; 20% se 5 anos ou mais e menos de 8; 30% se 8 anos ou mais. A lei diz que isto se aplica ao saldo «positivo ou negativo». (${_imp_V}.)`},
    {t:'cmp',id:'c1',head:['Tempo de detenção','Parte do ganho excluída','Taxa efetiva sobre o ganho','Imposto sobre 10 000 € de ganho'],rows:[
      ['Menos de 365 dias','0%',_imp_pc(_imp_T),_imp_e2(_imp_t(10000,0))],
      ['De 365 dias até 2 anos','0%',_imp_pc(_imp_T),_imp_e2(_imp_t(10000,0))],
      ['Mais de 2 anos e menos de 5','10%',_imp_pc(_imp_T*0.9),_imp_e2(_imp_t(10000,0.1))],
      ['5 anos ou mais e menos de 8','20%',_imp_pc(_imp_T*0.8),_imp_e2(_imp_t(10000,0.2))],
      ['8 anos ou mais','30%',_imp_pc(_imp_T*0.7),_imp_e2(_imp_t(10000,0.3))]],
      cap:'A «taxa efetiva» é uma conta nossa (28% sobre a parte que fica tributada), para comparar; a lei fala na parte do rendimento que é excluída. Abaixo de 365 dias pode haver englobamento obrigatório (ver abaixo).'},
    {t:'note',id:'n0',pending:true,x:'A lei de 2024 não tem artigo transitório no texto que consultámos. Como a AT conta o prazo de quem comprou antes de 29/06/2024, e como se combinam vendas de lotes com prazos diferentes no mesmo ano, deve ser confirmado nas instruções do Modelo 3 ou junto da AT. O Código também prevê que, para valores idênticos, se consideram vendidos primeiro os adquiridos há mais tempo, e que a regra se aplica separadamente em cada instituição onde os tens.'},
    {t:'p',id:'p3b',x:'Nota um pormenor útil: o Modelo 3 de 2026 tem, no quadro das vendas de valores mobiliários do Anexo J, uma coluna nova onde indicas se a operação respeita a valores admitidos à negociação ou a partes de fundos abertos. É por aí que a AT sabe se esta regra se pode aplicar.'},
    {t:'h',id:'h4',x:'Os 365 dias e o englobamento'},
    {t:'p',id:'p4',x:'Em vez da taxa especial, podes optar por somar o ganho ao resto do rendimento (<b>englobamento</b>, tema «Englobamento: quando compensa»). É <b>obrigatório</b> se o ativo foi detido há <b>menos de 365 dias</b> e o teu rendimento coletável, incluindo este saldo, atinge o último escalão do IRS (art. 72.º, n.º 14 do Código do IRS, em vigor desde 2023). O valor do último escalão muda todos os anos e está no artigo 68.º do Código do IRS, no Portal das Finanças; aqui não o escrevemos de propósito.'},
    {t:'h',id:'h5',x:'Um caso real: quando a lei muda a meio do jogo'},
    {t:'p',id:'p5',x:'Em 2022, a Lei n.º 12/2022 introduziu o englobamento obrigatório para ganhos de ativos com menos de um ano, para quem estava no topo da tabela do IRS. Dois anos depois, a Lei n.º 31/2024 foi na direção contrária e premiou quem fica muito tempo. Duas mudanças em dois anos, em sentidos opostos, mostram uma coisa prática: as regras fiscais não são fixas. Guarda sempre a data e a fonte do que aprendeste, e confirma no Portal das Finanças antes de decidir uma venda grande.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Achar que o imposto se paga sempre que o preço sobe. Só há imposto na venda (realização do ganho).',
      'Esquecer as comissões e o preço de cada compra: sem eles, o ganho calcula-se mal e não o consegues justificar.',
      'Vender perto do fim dos 365 dias, ou dos 2 anos, sem contar o prazo com cuidado: uma semana de diferença pode mudar a taxa efetiva.',
      'Escolher uma corretora fora de Portugal e pensar que ninguém tem de declarar. Em regra és tu, residente fiscal em Portugal, quem declara tudo.',
      'Fixar-se só no imposto. Um bom investimento não deve ser vendido ou mantido apenas por causa de 2 pontos percentuais.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p7',x:'Os ETFs UCITS que se compram cá (por exemplo, os que replicam o S&P 500) são fundos domiciliados noutros países, como a Irlanda. Segundo o guia da AT de outubro de 2023, as mais-valias do resgate ou da venda de fundos não residentes são tributadas à taxa autónoma de 28% e declaram-se no <b>Anexo J, quadro 9.2A, código G20</b>. Se a corretora é estrangeira, ninguém reteve nada em Portugal: o cálculo e a declaração ficam por tua conta (tema «Declarar no IRS: Modelo 3, anexos G e J»).'},
    {t:'note',id:'n1',x:'Conteúdo educativo, não é aconselhamento fiscal. O valor do último escalão muda todos os anos: confirma no Portal das Finanças. Para o teu caso concreto, fala com um contabilista.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'O imposto aparece na venda, sobre o saldo anual positivo de ganhos e perdas: taxa de 28%.',
      'Ganho = venda − compra − despesas. Guarda as notas de execução.',
      'Em ações e ETFs cotados detidos há mais de 2 anos, parte do ganho fica fora do imposto (10%, 20% ou 30%).',
      'Detido menos de 365 dias e no último escalão do IRS, o englobamento é obrigatório.',
      'Em corretoras estrangeiras o cálculo e a declaração são teus.']},
    {t:'fazve',id:'q1',ensina:['w1','p2b','h1'],q:'Compraste ETFs por 8 000 € e vendeste-os por 9 500 €, com 20 € de comissões no total. Quanto imposto pagas à taxa especial de 28% (sem outros ganhos nem perdas no ano)?',unit:'€',answer:_ex.imposto,tol:.02,why:`Ganho = 9 500 − 8 000 − 20 = 1 480 €. Imposto = 1 480 × 28% = ${_e(_ex.imposto)}. Ficas com ${_e(1480-_ex.imposto)} de lucro.`},
    {t:'fazve',id:'q2',ensina:['p3','c1'],q:'Tiveste um ganho de 10 000 € num ETF cotado que detiveste durante 6 anos, e não tens mais operações no ano. Quanto imposto pagas (28% sobre a parte que fica tributada)?',unit:'€',answer:_imp_t(10000,0.2),tol:.01,why:`Entre 5 e 8 anos fica excluída 20% do ganho: ficam 8 000 € a tributar. 8 000 × 28% = ${_e(_imp_t(10000,0.2))}. Sem a regra seriam ${_e(_imp_t(10000,0))}.`},
    {t:'decide',id:'q3',ensina:['p4'],label:'Decide',q:'Vendes um ETF que tinhas há 200 dias e o teu rendimento total está no último escalão do IRS. Podes escolher não englobar?',o:['Sim, a taxa especial é sempre uma opção','Não: o englobamento é obrigatório neste caso','Só se vender antes de 31 de dezembro'],c:1,why:'Detido há menos de 365 dias e no último escalão, o saldo tem de ser englobado (art. 72.º, n.º 14 do Código do IRS). Vender só depois de 365 dias evitaria esta regra.'},
    {t:'erro',id:'q4',ensina:['p0','p2'],label:'Encontra o erro',q:'Um amigo diz: «O meu ETF subiu 30% este ano, por isso já tenho de pagar imposto em abril, mesmo sem vender nada.» Onde está o erro?',o:['Não há erro: o imposto é anual sobre a subida','Só há imposto na venda: a subida sem venda é um ganho «no papel»','O imposto só se paga depois de 10 anos'],c:1,why:'As mais-valias só são tributadas quando o ativo é vendido (ou resgatado). Enquanto não vendes, o ganho não está realizado e não há mais-valia para declarar.'}
  ], src:[_AT_72,_imp_43,_imp_L31,_imp_OF,_AT_GUIA,{l:'Portal das Finanças: artigo 51.º do Código do IRS (despesas na compra e venda)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs51.aspx'}] },

{ id:'menos-valias', topic:'impostos', o:2, title:'Menos-valias: perdas, saldo anual e reporte para anos seguintes', mins:8,
  lead:'Vender com prejuízo também tem consequências fiscais, e podem ser boas: a perda pode abater aos ganhos do mesmo ano e, em certas condições, ser guardada para os anos seguintes. Mas as regras são mais estreitas do que muita gente pensa.',
  blocks:[
    {t:'h',id:'h0',x:'A conta corrente do ano'},
    {t:'p',id:'p0',x:'Pensa numa conta corrente em que, ao longo do ano civil, vais lançando os ganhos e as perdas das tuas vendas de ações e fundos. No fim do ano, o que importa é o <b>saldo</b>. Se for positivo, paga imposto. Se for negativo, não paga nada nesse ano. É por isso que uma perda «paga» parte do imposto de um ganho: reduz o saldo.'},
    {t:'p',id:'p0b',x:'Há uma condição importante: a perda só existe fiscalmente quando <b>vendes</b>. Se o ETF desce 30% e o manténs, é uma perda «no papel» que não aparece em lado nenhum da declaração. Quem vendeu em pânico em março de 2020 realizou a perda. Quem aguentou não realizou nenhuma, e quem voltou a comprar pagou mais pelas mesmas unidades se o preço entretanto subiu. Fiscalmente, o gesto de vender é o que conta.'},
    {t:'h',id:'h1',x:'O que entra no saldo e o que fica de fora'},
    {t:'p',id:'p1',x:'O Código do IRS fala em «saldo entre mais-valias e menos-valias» para as operações com ações, obrigações, unidades de participação em fundos e outros valores mobiliários (alíneas do artigo 10.º, n.º 1). Mais importante: segundo o artigo 55.º, <b>um resultado negativo numa categoria só pode ser abatido a resultados positivos da mesma categoria</b>. Isto tem uma consequência direta, que a tabela mostra.'},
    {t:'cmp',id:'c1',head:['A perda vem de…','Pode abater a…','Não abate a…'],rows:[
      ['Venda de ações ou ETFs (categoria G)','Ganhos de venda de ações, ETFs e outros valores mobiliários (categoria G)','Dividendos e juros (categoria E)'],
      ['Rendas com prejuízo (categoria F)','Rendas positivas de anos seguintes, até 6 anos','Ganhos de ações']],
      cap:'Fonte: artigo 55.º do Código do IRS, n.º 1. Os prazos de reporte dependem da categoria.'},
    {t:'p',id:'p1b',x:'Um pormenor que apanha muita gente: a perda numa ação <b>não</b> reduz o imposto sobre os dividendos que recebeste de outra. São categorias diferentes (G e E). Por outro lado, perdas e ganhos de ações e ETFs vendidos no mesmo ano ficam todos no mesmo saldo.'},
    {t:'h',id:'h2',x:'Quando o saldo do ano fica negativo: o reporte'},
    {t:'p',id:'p2',x:'Se o saldo do ano é negativo, o Código permite, em certas condições, guardar essa perda para <b>os cinco anos seguintes</b> e deduzi-la a ganhos da mesma natureza que venhas a obter. A condição, segundo o artigo 55.º, n.º 1, alínea d), é que o contribuinte <b>opte por englobar ou seja obrigado a englobar</b> esses rendimentos. O guia da AT diz o mesmo: o saldo negativo pode ser reportado aos cinco anos seguintes «quando o contribuinte opta pelo englobamento».'},
    {t:'p',id:'p2b',x:'Na prática, isto cria uma escolha que convém conhecer antes de entregar a declaração: em anos de perda, não pagas imposto de qualquer forma, mas a opção que escolhes na declaração pode decidir se a perda fica disponível para o futuro.'},
    {t:'note',id:'n0',pending:true,x:'O texto do artigo 55.º e o guia da AT dizem que o reporte depende do englobamento, mas não detalham, para quem opta no ano da perda, como se conjuga o aproveitamento nos anos seguintes com a taxa especial de 28%. Antes de contar com este reporte, confirma o procedimento no Anexo J/G do Modelo 3 do ano ou fala com um contabilista.'},
    {t:'h',id:'h3',x:'Um exemplo com números'},
    {t:'p',id:'p3',x:`<b>Ano 1.</b> Vendes um ETF com ganho de ${_imp_e2(3000)} e uma ação com perda de ${_imp_e2(1800)}. Saldo = ${_imp_e2(1200)}. Imposto a 28% = ${_imp_e2(1200*0.28)}. Sem a perda, o imposto seria ${_imp_e2(3000*0.28)}: a perda poupou-te ${_imp_e2(1800*0.28)}.`},
    {t:'p',id:'p3b',x:`<b>Ano 2.</b> Só tens perdas: ${_imp_e2(2000)} de saldo negativo. Imposto: zero. Se a perda puder ser reportada, no ano 3 vendes com ganho de ${_imp_e2(2500)}, e a base fica em ${_imp_e2(2500-2000)} (2 500 − 2 000), em vez de 2 500. Isto, claro, é uma simplificação: o resultado final depende da forma como declaras nesse ano.`},
    {t:'h',id:'h4',x:'Cuidados com a regra de 2024 e com perdas «estranhas»'},
    {t:'p',id:'p4',x:'A lei de 2024 sobre tempo de detenção (tema «Mais-valias: quanto imposto pagas ao vender») diz que a parte excluída (10%, 20% ou 30%) se aplica a um saldo «positivo ou negativo». Ou seja, também uma perda de um ativo detido durante muito tempo é considerada só em parte. Por outro lado, o artigo 43.º diz que as perdas com contraparte localizada em jurisdição de regime fiscal claramente mais favorável (lista oficial) <b>não são consideradas</b>.'},
    {t:'p',id:'p4b',x:'Também não podes contar o prejuízo de um investimento que «ainda» não vendeste, nem a descida de um fundo de que ainda és titular.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Pensar que a perda de ações abate ao imposto dos juros e dividendos. Não abate: são categorias diferentes.',
      'Vender só para «gerar prejuízo» fiscal e comprar de volta, sem perceber se o custo da operação compensa a poupança. Não encontrámos nas fontes oficiais consultadas uma regra específica para este caso: confirma antes.',
      'Não declarar um ano de perdas: sem declaração, não tens como mostrar à AT o saldo que queres reportar mais tarde.',
      'Perder as notas de execução: sem elas não provas o prejuízo.',
      'Achar que uma perda é «grátis»: o imposto que poupas é, no máximo, 28% da perda. Perder 1 000 € poupa 280 € de imposto, não 1 000 €.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'As regras aplicam-se a quem é residente fiscal em Portugal, tenha as ações numa corretora portuguesa ou estrangeira. Em corretoras de fora, calculas e declaras tu as perdas no Anexo J. Para fundos imobiliários e outros, as regras variam: consulta o tema «Declarar no IRS: Modelo 3, anexos G e J».'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'O que conta é o saldo do ano civil: ganhos menos perdas das vendas.',
      'Só há perda fiscal quando vendes.',
      'Uma perda de ações só abate a ganhos de ações e valores mobiliários, não a dividendos nem a juros.',
      'O reporte para cinco anos existe, mas só quando se opta (ou se é obrigado) a englobar.',
      'A perda poupa, no máximo, os 28% do seu valor.']},
    {t:'fazve',id:'q1',ensina:['p0','p3'],q:'No mesmo ano vendes um ETF com ganho de 3 000 € e uma ação com perda de 1 800 €, sem outras operações. Quanto imposto pagas à taxa de 28%?',unit:'€',answer:(3000-1800)*0.28,tol:.01,why:`Saldo = 3 000 − 1 800 = 1 200 €. Imposto = 1 200 × 28% = ${_imp_e2(1200*0.28)}.`},
    {t:'decide',id:'q2',ensina:['p2'],label:'Decide',q:'Tiveste um saldo negativo de 2 000 € este ano. Segundo o artigo 55.º, a que condição o reporte aos cinco anos seguintes está ligado?',o:['Ter vendido há menos de 365 dias','Optar por englobar (ou ser obrigado a englobar) esses rendimentos','Ter uma corretora portuguesa'],c:1,why:'O artigo 55.º, n.º 1, alínea d), liga o reporte de cinco anos ao englobamento: «quando o sujeito passivo opte ou seja obrigado a englobar esses rendimentos».'},
    {t:'erro',id:'q3',ensina:['p1','c1'],label:'Encontra o erro',q:'Um amigo diz: «Perdi 1 000 € numa ação, por isso este ano não pago imposto sobre os dividendos que recebi.» Onde está o erro?',o:['Não há erro','A perda de ações é da categoria G e os dividendos da categoria E: não se compensam','Os dividendos nunca pagam imposto'],c:1,why:'Segundo o artigo 55.º, um resultado negativo só pode abater a resultados positivos da mesma categoria. Perdas de ações não reduzem o imposto de dividendos ou juros.'},
    {t:'fazve',id:'q4',ensina:['p3','p3b'],q:'Tens um saldo negativo reportável de 2 000 € e, no ano seguinte, um ganho de 2 500 €. Qual é a base do ganho depois de deduzir a perda reportada?',unit:'€',answer:500,tol:.01,why:'2 500 − 2 000 = 500 €. A base é de 500 €, desde que o reporte seja aplicável no teu caso (condições do artigo 55.º).'}
  ], src:[_imp_55,_imp_43,_AT_72,_AT_GUIA,_imp_L31] },

{ id:'dividendos-juros', topic:'impostos', o:3, title:'Dividendos e juros', mins:8,
  lead:'Os rendimentos que recebes de aplicações, juros e dividendos, são tributados à taxa de 28% na grande maioria dos casos, e muitas vezes o imposto é retido antes de o dinheiro chegar a ti. Quando o rendimento vem de fora, o trabalho de declarar passa para ti.',
  blocks:[
    {t:'h',id:'h0',x:'A árvore e os frutos'},
    {t:'p',id:'p0',x:'Um pomar dá frutos todos os anos e a árvore continua lá. Um depósito a prazo ou uma ação funcionam assim: o capital fica contigo e vai dando <b>juros</b> (no caso do banco) ou <b>dividendos</b> (no caso de uma empresa que reparte parte do lucro pelos acionistas). A Autoridade Tributária chama-lhes <b>rendimentos de capitais</b> (categoria E) e tributa só o rendimento, nunca o capital que investiste.'},
    {t:'h',id:'h1',x:'Quando o rendimento vem de Portugal: o imposto chega retido'},
    {t:'p',id:'p1',x:'Quando os juros ou os dividendos são pagos por uma entidade em Portugal (ou por intermédio de uma entidade em Portugal, como o banco ou a corretora onde tens os títulos), essa entidade retém <b>28% na fonte</b>, a título definitivo (taxa liberatória). O que recebes já vem líquido, e em regra não tens de os declarar, a não ser que optes pelo englobamento. Isto está no artigo 71.º do Código do IRS e no guia da AT de outubro de 2023 (' + _imp_V + ').'},
    {t:'w',id:'w1',w:'calc',c:'netint'},
    {t:'p',id:'p1b',x:'Os dividendos de uma empresa portuguesa são um caso especial se optares por englobar: o artigo 40.º-A do Código do IRS faz com que só <b>50% do dividendo</b> entre na soma. Detalhes no tema «Englobamento: quando compensa».'},
    {t:'h',id:'h2',x:'Quando o rendimento vem de fora'},
    {t:'p',id:'p2',x:'Se os rendimentos vêm de uma entidade <b>no estrangeiro</b> e ninguém em Portugal os pagou nem os registou, a retenção portuguesa não existe e tens de os declarar tu, no <b>Anexo J</b> do Modelo 3. A taxa especial continua a ser 28%, com opção de englobamento. Segundo o guia da AT, os dividendos estrangeiros declaram-se no quadro 8A do Anexo J: com o <b>código E11</b> se não houve retenção em Portugal, ou com o <b>código E10</b> se houve (e, nesse caso, assinalas «SIM» no quadro 8B para optar pelo englobamento).'},
    {t:'ul',id:'u1',x:[
      '<b>Anexo E</b>: rendimentos de capitais obtidos em Portugal, usado sobretudo quando se opta por englobar (quadro 4B).',
      '<b>Anexo J</b>: rendimentos obtidos no estrangeiro. Quadro 8A para juros e dividendos; quadro 8B para a opção de englobar.',
      'Juros de contas no estrangeiro: <b>código E21</b> (quadro 8A) se a taxa é de 28%. O guia refere ainda o código E99 para o caso de entidades em jurisdições de regime fiscal claramente mais favorável, com taxa de 35%.',
      'Se tens contas bancárias no estrangeiro, o Anexo J (quadro 11) pede a identificação por IBAN e BIC, mesmo sem juros.']},
    {t:'h',id:'h3',x:'O imposto também pode ser cobrado lá fora: o crédito de imposto'},
    {t:'p',id:'p3',x:'O país onde está a empresa pode reter imposto sobre o dividendo antes de o pagar, e depois Portugal quer 28% sobre o mesmo valor. Para não pagares duas vezes, o artigo 81.º do Código do IRS prevê um <b>crédito de imposto</b>: abates ao IRS português o imposto pago lá fora, com um limite, que é o menor entre o imposto pago no estrangeiro e a parte do IRS português que corresponde a esse rendimento. Se existir uma convenção entre os dois países, o crédito não pode ultrapassar o imposto que a convenção permite cobrar lá. O guia da AT acrescenta que, para juros, precisas de um documento da autoridade fiscal do outro país que comprove o rendimento e o imposto pago.'},
    {t:'p',id:'p3b',x:`Um exemplo com percentagens de <b>exemplo</b> (não é a taxa de nenhum país em concreto): recebes ${_imp_e2(1000)} brutos de uma empresa estrangeira e o país da fonte retém 15%, ou seja ${_imp_e2(150)}. Em Portugal, 28% de ${_imp_e2(1000)} dão ${_imp_e2(280)}. O crédito é o menor entre ${_imp_e2(150)} e ${_imp_e2(280)}, isto é, ${_imp_e2(150)}. Pagas mais ${_imp_e2(280-150)} em Portugal, e o total de imposto é ${_imp_e2(280)}, os mesmos 28%. Se o país da fonte retivesse 30% (${_imp_e2(300)}), o crédito ficaria limitado a ${_imp_e2(280)}, e os ${_imp_e2(20)} a mais já não os recuperavas em Portugal nesse ano.`},
    {t:'cmp',id:'c1',head:['Origem do rendimento','Quem retém','O que fazes tu'],rows:[
      ['Depósito ou títulos num banco/corretora em Portugal','A entidade portuguesa, 28% a título definitivo','Normalmente nada (ou Anexo E, se englobas)'],
      ['Dividendos de ação estrangeira numa corretora estrangeira','Ninguém em Portugal (o país da fonte pode reter)','Anexo J, quadro 8A, código E11; pedes crédito de imposto se houver imposto lá fora'],
      ['Distribuições de um ETF UCITS (fundo não residente)','Ninguém, na corretora estrangeira','Anexo J, quadro 8A, código E22 (tema «ETFs de acumulação e de distribuição»)']],
      cap:'Fonte: guia da AT «Tributação de produtos financeiros em sede de IRS», outubro de 2023. O modelo muda: confirma os códigos no ano em que declaras.'},
    {t:'note',id:'n1',pending:true,x:'Os códigos e quadros acima vêm do guia da AT de outubro de 2023. O Ofício-Circulado da AT de março de 2026 confirma que o Anexo J se mantém, mas não repete estes códigos: antes de declarar, confirma-os nas instruções do Modelo 3 em vigor.'},
    {t:'h',id:'h4',x:'Um caso real: quando o dividendo desaparece'},
    {t:'p',id:'p4',x:'No início de 2020, com a pandemia, o Banco Central Europeu recomendou aos bancos da zona euro que não pagassem dividendos, e muitas empresas de outros setores suspenderam-nos. Quem vivia dos dividendos de uma carteira viu o rendimento cair de um dia para o outro. Os dividendos <b>não são garantidos</b>: a empresa decide, ano a ano, quanto distribui. O mesmo não vale para os juros de um depósito, que estão contratados.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que 28% é o imposto total quando o rendimento é estrangeiro e já houve retenção lá: sem pedir o crédito de imposto, podes pagar duas vezes.',
      'Esquecer-se de declarar dividendos que a corretora estrangeira te pagou. A obrigação é tua.',
      'Comparar rendimentos brutos com líquidos. Um dividendo de 4% bruto são 2,88% depois dos 28%.',
      'Trocar sem pensar um fundo de distribuição por um de acumulação só por causa do imposto, sem ver custos, risco e a tua situação.',
      'Pensar que o englobamento é sempre pior por «declarar mais». Pode compensar a quem tem rendimentos baixos.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Se compras ações portuguesas através de um banco ou corretora com sede cá, os dividendos chegam com 28% retidos e não precisas de fazer nada. Se usas uma corretora estrangeira, tens de declarar tudo no Anexo J (tema «Declarar no IRS: Modelo 3, anexos G e J»). Os juros dos depósitos seguem a mesma lógica (tema «Retenção na fonte»). Nos Certificados de Aforro, o produto de poupança do Estado, os juros já são pagos líquidos de IRS.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Juros e dividendos são rendimentos de capitais (categoria E): 28% em regra.',
      'Se uma entidade em Portugal paga ou regista os títulos, retém 28% e fica tudo resolvido.',
      'Rendimentos de fora declaram-se no Anexo J (quadro 8A); a opção de englobar faz-se no quadro 8B.',
      'O crédito de imposto (art. 81.º) evita pagar duas vezes pelo mesmo rendimento, com um limite.',
      'Dividendos não são garantidos; juros de depósito são contratados.']},
    {t:'fazve',id:'q1',ensina:['p1','w1'],q:'Recebeste 200 € de dividendos de uma empresa portuguesa, com retenção de 28% na fonte. Quanto recebes líquido?',unit:'€',answer:144,tol:.01,why:'28% de 200 € = 56 €. Líquido: 144 €.'},
    {t:'fazve',id:'q2',ensina:['p3','p3b'],q:'Recebes 1 000 € de dividendos de uma empresa estrangeira; o país da fonte reteve 15% (valor de exemplo). Em Portugal tens 28%, com crédito de imposto. Quanto pagas ainda em Portugal?',unit:'€',answer:130,tol:.01,why:'28% de 1 000 € = 280 €. Crédito = o menor entre 150 € (pago lá) e 280 € = 150 €. Pagas em Portugal 280 − 150 = 130 €.'},
    {t:'decide',id:'q3',ensina:['p2','u1'],label:'Decide',q:'Recebes dividendos de ações através de uma corretora de outro país da UE, e ninguém em Portugal reteve imposto. Quem declara à AT?',o:['A corretora, automaticamente','Tu, no Anexo J do Modelo 3','Ninguém tem de declarar'],c:1,why:'Os residentes em Portugal declaram os rendimentos de fonte estrangeira no Anexo J (quadro 8A, código E11 para dividendos sem retenção em Portugal).'},
    {t:'erro',id:'q4',ensina:['p3','p3b'],label:'Encontra o erro',q:'Um amigo diz: «Já pagaram 30% de imposto lá fora sobre o meu dividendo, por isso recupero tudo em Portugal.» Onde está o erro?',o:['Não há erro','O crédito de imposto tem limite: não ultrapassa a parte do IRS português correspondente a esse rendimento','Em Portugal os dividendos estrangeiros não pagam imposto'],c:1,why:'O artigo 81.º limita o crédito ao menor entre o imposto pago lá fora e a parte do IRS português que corresponde a esse rendimento. O excedente não é devolvido por Portugal nesse ano.'}
  ], src:[_AT_71,_AT_GUIA,_imp_81,{l:'Portal das Finanças: artigo 40.º-A do Código do IRS (dupla tributação económica)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs40a.aspx'},_imp_OF] },

{ id:'retencao', topic:'impostos', o:4, title:'Retenção na fonte', mins:6,
  lead:'Retenção na fonte é o imposto que alguém desconta antes de te pagar. Quando é feita em Portugal, simplifica; quando não é, o trabalho passa para ti. E nem toda a retenção quer dizer «acabou».',
  blocks:[
    {t:'h',id:'h0',x:'O cobrador que fica no caminho'},
    {t:'p',id:'p0',x:'Imagina que o teu patrão, em vez de te dar o ordenado todo e esperar que depois pagues o imposto, desconta logo uma parte e entrega-a ao Estado. É isto a retenção. A lei chama «substituto tributário» a quem desconta (o banco, a corretora, a empresa). Nos rendimentos de capitais, as entidades em Portugal têm de reter o imposto no momento do vencimento, do pagamento ou da colocação à disposição, e entregá-lo ao Estado.'},
    {t:'h',id:'h1',x:'Duas naturezas: definitiva ou por conta'},
    {t:'p',id:'p1',x:'Quando a retenção é feita <b>a título definitivo</b> (taxa liberatória, como nos juros de depósitos e nos dividendos), o imposto retido é o imposto devido e, em regra, não tens de declarar o rendimento, nem pagar mais nada. Se <b>optares por declarar</b> (englobar), a retenção passa a ser um <b>pagamento por conta</b>: é abatida ao IRS total que se apurar no fim, e se ficou a mais, recebes a diferença de volta. Isto vem do artigo 71.º do Código do IRS e do guia da AT de outubro de 2023.'},
    {t:'p',id:'p1b',x:`Um exemplo com números de <b>exemplo</b>: juros de ${_imp_e2(1000)}, com retenção de 28%, ou seja, ${_imp_e2(280)}. Se englobares e a tua taxa marginal for 15% (exemplo), o imposto desses juros seria ${_imp_e2(150)}. Os ${_imp_e2(280)} retidos passam a pagamento por conta, e a diferença de ${_imp_e2(280-150)} é devolvida no acerto final. Se a tua taxa marginal fosse 40%, o imposto seria ${_imp_e2(400)} e pagavas mais ${_imp_e2(400-280)}.`},
    {t:'h',id:'h2',x:'Quem retém, em cada caso'},
    {t:'cmp',id:'c1',head:['Onde recebes','Quem retém','O que fazes'],rows:[
      ['Banco ou corretora em Portugal (juros, dividendos)','A entidade, 28% a título definitivo','Normalmente nada, salvo englobamento'],
      ['Resgate de um fundo de investimento mobiliário português','A entidade, 28% a título definitivo','Normalmente nada (opção de englobar: Anexo G)'],
      ['Venda de ações (mais-valias)','Não há retenção','Declaras no Anexo G (ou J, se são de entidade não residente)'],
      ['Corretora ou banco no estrangeiro','Ninguém em Portugal','Declaras no Anexo J do Modelo 3']],
      cap:'Fonte: guia da AT de outubro de 2023. Cada produto tem a sua regra: o guia tem uma secção por produto.'},
    {t:'p',id:'p2',x:'As <b>mais-valias de ações</b> não têm retenção em Portugal: segundo o guia da AT, são sempre inscritas por ti na declaração. Já os rendimentos de fundos de investimento mobiliário <b>portugueses</b> (distribuições e resgates) são retidos a 28%. É por isso que o mesmo investidor pode ter, no mesmo ano, rendimentos «já tratados» e rendimentos que tem de declarar.'},
    {t:'h',id:'h3',x:'Quando o dinheiro vem de fora'},
    {t:'p',id:'p3',x:'Se a entidade que paga está fora de Portugal e não há nenhuma entidade portuguesa pelo meio, ninguém retém em Portugal. Isso não quer dizer que não haja imposto: tens de declarar o rendimento e pagar os 28% (ou englobar). O país da fonte pode, por seu lado, ter retido imposto; nesse caso, usas o crédito de imposto do artigo 81.º (tema «Dividendos e juros»). Quando há convenção para evitar a dupla tributação, o crédito não pode ultrapassar o imposto que a convenção permite cobrar no país da fonte.'},
    {t:'note',id:'n1',pending:true,x:'As taxas de retenção que cada país aplica a cada produto, e os formulários exigidos pelas corretoras estrangeiras para beneficiares de uma convenção, não ficaram confirmados em fonte oficial portuguesa. Confirma com a tua corretora e com o Portal das Finanças antes de contar com uma taxa.'},
    {t:'h',id:'h4',x:'Dois investidores, o mesmo ano (um caso hipotético)'},
    {t:'p',id:'p4',x:'A Marta tem um depósito e ações portuguesas num banco em Portugal. A Rita tem os mesmos rendimentos, mas numa corretora de outro país. No fim do ano, a Marta recebeu tudo «limpo»: o banco reteve os 28% e nada mais lhe é pedido. A Rita não recebeu nenhuma retenção portuguesa e tem de declarar os dividendos no Anexo J e as vendas de ações com os cálculos feitos por ela. O imposto (28%) é igual, mas o trabalho não. Por isso, antes de abrires conta numa corretora, descobre quem retém, quem declara e se te dão um relatório anual com os valores.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Achar que «retido» é o mesmo que «declarado». Só é verdade quando a retenção é definitiva e não optas por englobar.',
      'Não pedir o documento que prova o imposto retido (banco, corretora), se vais englobar.',
      'Contar com o imposto estrangeiro como se Portugal o devolvesse na totalidade: o crédito tem limite.',
      'Misturar produtos: o imposto sobre mais-valias de ações e o de dividendos são tratados em quadros diferentes.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Em bancos e corretoras portugueses, a retenção de 28% sobre juros e dividendos é a regra e simplifica tudo. Com corretoras estrangeiras, a responsabilidade é tua: ver o tema «Declarar no IRS: Modelo 3, anexos G e J». A retenção de IRS que as entidades fazem sobre salários, rendas e outros é uma realidade à parte e tem as suas tabelas (para as rendas, ver o tema «Rendimentos de imóveis: rendas (categoria F) e mais-valias de imóveis»).'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Retenção é imposto descontado por quem paga (o substituto tributário).',
      'Definitiva (liberatória): liquida o imposto, sem declarar. Por conta: se declaras, é abatida no acerto final.',
      'Mais-valias de ações não têm retenção em Portugal: declaras tu.',
      'Sem entidade portuguesa pelo meio, ninguém retém: o rendimento declara-se no Anexo J.',
      'Imposto retido lá fora pode dar direito a crédito, com limite.']},
    {t:'decide',id:'q1',ensina:['p1','c1'],label:'Decide',q:'O banco reteve 28% dos juros do teu depósito, a título definitivo. Tens de os declarar no Modelo 3?',o:['Sim, sempre','Em regra não, salvo se optares pelo englobamento','Só se forem mais de 100 €'],c:1,why:'A retenção a título definitivo liquida o imposto. Declaras apenas se optares por englobar.'},
    {t:'decide',id:'q2',ensina:['c1','p3'],label:'Decide',q:'Recebes dividendos numa corretora estrangeira. Quem faz a retenção portuguesa?',o:['A corretora estrangeira','Ninguém: declaras tu os rendimentos','O banco onde tens a conta'],c:1,why:'Sem entidade portuguesa a reter, tens de declarar os rendimentos no Anexo J.'},
    {t:'fazve',id:'q3',ensina:['p1','p1b'],q:'Juros de 1 000 € com 280 € retidos. Optas por englobar e o imposto desses juros, com a tua taxa marginal, dá 150 € (valor de exemplo). Quanto te é devolvido no acerto final?',unit:'€',answer:130,tol:.01,why:'Retido 280 €, imposto devido 150 €: a diferença de 130 € é devolvida, porque a retenção passou a pagamento por conta.'},
    {t:'erro',id:'q4',ensina:['p2','c1'],label:'Encontra o erro',q:'Um amigo diz: «A minha corretora portuguesa retém 28% sobre as vendas de ações com lucro, por isso nunca declaro mais-valias.» Onde está o erro?',o:['Não há erro','As mais-valias de ações não têm retenção em Portugal: é o investidor que as declara','As mais-valias de ações não pagam imposto'],c:1,why:'O guia da AT diz que as mais-valias de ações são de inscrição obrigatória na declaração (Anexo G ou J). A retenção a 28% existe para juros, dividendos e resgates de fundos portugueses, mas não para mais-valias de ações.'}
  ], src:[_AT_71,_AT_GUIA,_imp_81] },

{ id:'englobamento', topic:'impostos', o:5, title:'Englobamento: quando compensa', mins:8,
  lead:'Em vez da taxa fixa de 28%, podes somar certos rendimentos ao resto e tributar tudo pelas taxas progressivas do IRS. Compensa a quem tem rendimentos mais baixos, e pode não compensar a quem ganha mais. A conta faz-se com a tua taxa marginal.',
  blocks:[
    {t:'h',id:'h0',x:'Duas formas de tributar o mesmo euro'},
    {t:'p',id:'p0',x:'O regime normal do IRS é o <b>englobamento</b>: somam-se os rendimentos de todas as categorias do ano (salário, rendas, etc.) e aplica-se a tabela de taxas gerais (artigo 68.º do Código do IRS). Mas para certos rendimentos, como os juros, os dividendos ou as mais-valias de ações e ETFs, a lei dá-te outra via: uma <b>taxa especial</b> fixa, de 28%, aplicada só a esse rendimento. A taxa especial é o ponto de partida; o englobamento é uma opção que podes escolher na declaração.'},
    {t:'h',id:'h1',x:'Taxa média, taxa marginal e escalões'},
    {t:'p',id:'p1',x:'O IRS tem taxas <b>progressivas</b>: o teu rendimento é cortado em fatias (escalões) e cada fatia paga uma taxa mais alta do que a anterior. Não é o rendimento todo que paga a taxa do último escalão: só a parte que cai nesse escalão. A <b>taxa média</b> é o imposto total a dividir pelo rendimento. A <b>taxa marginal</b> é a taxa que incide sobre o <b>último euro</b> que ganhaste. É essa que decide se compensa englobar: ao somar mais um rendimento, é a taxa marginal que ele vai pagar.'},
    {t:'p',id:'p1b',x:'A tabela real (artigo 68.º do Código do IRS) muda todos os anos e, por isso, não escrevemos aqui os valores dos escalões. A redação em vigor para 2026 foi dada pelo Decreto-Lei n.º 212/2026, de 4 de novembro, segundo o Portal das Finanças. Para explicar o mecanismo usamos <b>escalões inventados</b>: 10% até 10 000 €, 25% dos 10 000 € aos 30 000 €, 40% acima. Não são os teus, só servem para a conta.'},
    {t:'h',id:'h2',x:'A conta: quando compensa'},
    {t:'p',id:'p2',x:'Se a tua taxa marginal for <b>inferior a 28%</b>, englobar reduz o imposto sobre esse rendimento. Se for <b>superior</b>, a taxa especial de 28% é melhor. É por isso que o englobamento ajuda sobretudo quem tem rendimentos baixos ou médios.'},
    {t:'cmp',id:'c1',head:['Rendimento de base (exemplo)','Imposto de englobar 5 000 € de ganho','Imposto com a taxa especial (28%)','Vantagem'],rows:[
      ['5 000 €',_imp_e2(_imp_marg(5000,5000)),_imp_e2(5000*_imp_T),'Englobar poupa '+_imp_e2(5000*_imp_T-_imp_marg(5000,5000))],
      ['20 000 €',_imp_e2(_imp_marg(20000,5000)),_imp_e2(5000*_imp_T),'Englobar poupa '+_imp_e2(5000*_imp_T-_imp_marg(20000,5000))],
      ['40 000 €',_imp_e2(_imp_marg(40000,5000)),_imp_e2(5000*_imp_T),'Taxa especial poupa '+_imp_e2(_imp_marg(40000,5000)-5000*_imp_T)]],
      cap:'Com escalões inventados (10%, 25%, 40%): serve só para mostrar o mecanismo. Os escalões reais estão no artigo 68.º do Código do IRS.'},
    {t:'p',id:'p2b',x:`Repara no que acontece: com um rendimento de ${_imp_e2(20000)}, o ganho de ${_imp_e2(5000)} cai todo no escalão de 25% (porque ${_imp_e2(20000)} + ${_imp_e2(5000)} = ${_imp_e2(25000)}, ainda abaixo de ${_imp_e2(30000)}). O imposto adicional é ${_imp_e2(_imp_marg(20000,5000))} e a taxa especial daria ${_imp_e2(5000*_imp_T)}. Com ${_imp_e2(40000)}, o ganho cai no escalão de 40% e englobar custa mais. A <b>decisão muda com a tua taxa marginal</b>, não com o tamanho do ganho.`},
    {t:'h',id:'h3',x:'Os dividendos de empresas portuguesas têm um desconto'},
    {t:'p',id:'p3',x:`O artigo 40.º-A do Código do IRS diz que, se optares por englobar, os lucros distribuídos por sociedades portuguesas sujeitas a IRC contam apenas por <b>50% do seu valor</b>. O guia da AT diz o mesmo para dividendos de entidades da UE ou do EEE que cumpram as condições da Diretiva 2011/96/UE (a das sociedades-mães e afiliadas, pensada para participações empresariais). Exemplo, com os escalões inventados e um rendimento de ${_imp_e2(20000)}: um dividendo de ${_imp_e2(1000)} paga ${_imp_e2(280)} à taxa especial. Se englobares, entram só ${_imp_e2(500)} na soma e o imposto extra é ${_imp_e2(_imp_marg(20000,500))}. Mas atenção: optar pelo englobamento obriga a englobar <b>todos</b> os rendimentos de capitais (categoria E) desse ano, incluindo os juros, que não têm esta redução.`},
    {t:'h',id:'h4',x:'As regras do jogo'},
    {t:'ul',id:'u1',x:[
      '<b>A opção é por categoria</b>: ao optares por englobar um rendimento, ficas obrigado a englobar todos os rendimentos da mesma categoria (o guia da AT di-lo para a categoria E e para a categoria G).',
      '<b>Onde se marca</b>: nas mais-valias, no quadro 15 do Anexo G, com «SIM»; nos rendimentos de capitais, no Anexo E (quadro 4B); no estrangeiro, nos quadros 8B ou 9.2C do Anexo J (segundo o guia da AT de outubro de 2023).',
      '<b>A retenção</b>: o imposto já retido deixa de ser definitivo e passa a pagamento por conta, abatido no acerto final.',
      '<b>Obrigatório em alguns casos</b>: mais-valias de ativos detidos há menos de 365 dias, se o rendimento coletável atinge o último escalão do IRS (art. 72.º, n.º 14).',
      '<b>Perdas</b>: o reporte do saldo negativo a cinco anos está ligado ao englobamento (tema «Menos-valias: perdas, saldo anual e reporte para anos seguintes»).',
      '<b>Imóveis</b>: as mais-valias da venda de casas não estão na lista de taxas especiais do artigo 72.º, n.º 1, alínea c): entram no englobamento, só com 50% do saldo a contar (tema «Rendimentos de imóveis: rendas (categoria F) e mais-valias de imóveis»).']},
    {t:'note',id:'n0',pending:true,x:'Somar rendimentos aumenta o rendimento coletável, o que pode alterar outros cálculos da declaração (por exemplo, deduções que dependem do rendimento). Isto não ficou confirmado em fonte oficial para cada caso: faz as duas contas no Portal das Finanças, com e sem a opção, antes de decidir.'},
    {t:'h',id:'h5',x:'Um caso real: a mudança de 2023'},
    {t:'p',id:'p5',x:'Até 2022, quem tinha rendimentos altos podia sempre ficar com os 28% nas mais-valias de ações, vendesse quando vendesse. A Lei n.º 12/2022 introduziu o englobamento obrigatório para ganhos de ativos detidos há menos de um ano, para quem estiver no último escalão. A mensagem do legislador foi clara: a taxa de 28% é uma vantagem para o investimento de médio e longo prazo, não para a especulação de curto prazo de quem já ganha muito. Em 2024, a Lei n.º 31/2024 reforçou essa direção com o desconto para quem fica mais de dois anos (tema «Mais-valias: quanto imposto pagas ao vender»).'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Comparar o teu rendimento com os 28% em vez da tua taxa marginal. O que conta é a taxa do último euro.',
      'Pensar que englobar um dividendo obriga a englobar só esse dividendo: obriga a englobar os rendimentos da mesma categoria.',
      'Optar sem fazer a conta. Basta preencher a declaração com e sem a opção e comparar o resultado.',
      'Esquecer que o artigo 68.º muda todos os anos: a decisão pode mudar de ano para ano.',
      'Ignorar o caso obrigatório (menos de 365 dias e último escalão): aí a escolha não existe.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p7',x:'A opção é feita na declaração Modelo 3, enviada no Portal das Finanças. Faz sempre as duas contas: preenche a declaração com e sem a opção e compara o resultado final. Com corretoras estrangeiras, o englobamento declara-se no Anexo J; com bancos e corretoras portuguesas que retêm 28%, o englobamento passa pelo Anexo E (tema «Declarar no IRS: Modelo 3, anexos G e J»).'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Taxa especial: 28% fixos sobre juros, dividendos e mais-valias. Englobamento: soma-se ao resto e aplica-se a tabela do artigo 68.º.',
      'A taxa marginal é a taxa do último euro. Marginal abaixo de 28%: englobar compensa. Acima: não.',
      'Em dividendos de empresas portuguesas, englobar conta só 50% do valor.',
      'Optar por englobar obriga a englobar todos os rendimentos da mesma categoria.',
      'É obrigatório em mais-valias de ativos com menos de 365 dias, no último escalão.']},
    {t:'fazve',id:'q1',ensina:['p2','c1'],q:'Tens uma mais-valia de 1 000 € e uma taxa marginal (hipotética) de 30%. A taxa especial é 28%. Quanto pagas a mais se englobares, em vez de usares a taxa especial?',unit:'€',answer:20,tol:.02,why:'Com 28%: 280 €. Com 30%: 300 €. Pagas mais 20 € ao englobar. A taxa marginal de 30% é um valor de exemplo.'},
    {t:'decide',id:'q2',ensina:['p2','c1'],label:'Decide',q:'A tua taxa marginal de IRS é muito inferior a 28%. O que é mais provável que compense?',o:['Manter a taxa especial de 28%','É sempre igual','Optar pelo englobamento'],c:2,why:'Com uma taxa marginal inferior a 28%, tributar os rendimentos às taxas progressivas costuma sair mais barato.'},
    {t:'fazve',id:'q3',ensina:['p3','p2b'],q:'Com escalões inventados, o imposto extra de englobar um dividendo de 1 000 € (conta só 50%) a um rendimento de 20 000 € é 125 €. Com a taxa especial seria 280 €. Quanto poupas ao englobar?',unit:'€',answer:280-_imp_marg(20000,500),tol:.01,why:`${_imp_e2(280)} − ${_imp_e2(_imp_marg(20000,500))} = ${_imp_e2(280-_imp_marg(20000,500))}. Só entram 500 € (50% de 1 000 €) no escalão de 25%.`},
    {t:'erro',id:'q4',ensina:['u1'],label:'Encontra o erro',q:'Um amigo diz: «Optei por englobar os dividendos, mas os juros do meu depósito deixo-os de fora, porque já tiveram retenção.» Onde está o erro?',o:['Não há erro: cada rendimento escolhe-se à parte','Ao optar por englobar, ficas obrigado a englobar todos os rendimentos da mesma categoria, juros incluídos','Os juros nunca se englobam'],c:1,why:'O guia da AT diz que quem opta pelo englobamento tem de englobar a totalidade dos rendimentos da categoria E (juros e dividendos incluídos).'}
  ], src:[_AT_72,_imp_68,{l:'Portal das Finanças: artigo 40.º-A do Código do IRS (dupla tributação económica)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs40a.aspx'},_AT_GUIA,_imp_L31] },

{ id:'acc-dist', topic:'impostos', o:6, title:'ETFs de acumulação e de distribuição', mins:8,
  lead:'Dois ETFs iguais, um que paga dividendos e outro que os reinveste. O imposto é o mesmo em percentagem, mas muda quando o pagas, e com o tempo essa diferença cresce.',
  blocks:[
    {t:'h',id:'h0',x:'Duas formas de receber o mesmo fruto'},
    {t:'p',id:'p0',x:'Pensa numa macieira. Podes colher as maçãs todos os anos e vendê-las (<b>distribuição</b>), ou deixá-las cair no chão e adubar a própria árvore, que cresce mais (<b>acumulação</b>). Os dois ETFs têm as mesmas ações lá dentro e dão o mesmo retorno total, antes de impostos. A diferença é o que acontece aos dividendos que as empresas pagam: o ETF de distribuição passa-os para a tua conta; o de acumulação reinveste-os dentro do fundo.'},
    {t:'h',id:'h1',x:'O que diz a Autoridade Tributária'},
    {t:'p',id:'p1',x:'Os ETFs UCITS que se compram a partir de Portugal são, em regra, fundos <b>não residentes</b> (por exemplo, domiciliados na Irlanda). Segundo o guia da AT de outubro de 2023, os rendimentos <b>distribuídos</b> por fundos não residentes são rendimentos de capitais (categoria E), tributados à taxa especial de 28%, e inscrevem-se sempre no <b>Anexo J, quadro 8A, código E22</b> (a opção de englobar marca-se no quadro 8B). O <b>resgate ou a venda</b> das unidades gera uma mais-valia (categoria G), também a 28%, declarada no <b>Anexo J, quadro 9.2A, código G20</b> (englobamento no quadro 9.2C). O Ofício-Circulado de 2026 confirma que o código G20 continua em uso no Modelo 3 em vigor.'},
    {t:'p',id:'p1b',x:'Em resumo, o guia descreve duas formas de rendimento nos fundos não residentes: a distribuição e o resgate/alienação. Um ETF de acumulação não distribui nada, por isso, nesta leitura, <b>não há imposto de capitais todos os anos</b>: o imposto aparece na venda, como mais-valia. É por isso que a regra de 2024 (tema «Mais-valias: quanto imposto pagas ao vender») importa a quem acumula: a parte de ganho excluída por detenção de 2, 5 ou 8 anos aplica-se à mais-valia final, mas não aos dividendos recebidos.'},
    {t:'note',id:'n1',pending:true,x:'O guia da AT não trata expressamente os ETFs de acumulação: a conclusão de que não há imposto antes da venda decorre das duas formas de rendimento que descreve (distribuição e resgate/alienação). Também não está confirmado o tratamento de situações especiais (por exemplo, fundos domiciliados em jurisdições de regime fiscal claramente mais favorável, que o guia trata à parte). Confirma com a AT ou com um contabilista antes de contar com este regime em valores elevados.'},
    {t:'h',id:'h2',x:'A diferença em números'},
    {t:'p',id:'p2',x:`Um modelo simples, com valores de <b>exemplo</b> (sem comissões, custos nem inflação): investes ${_imp_e2(10000)} durante 20 anos, o retorno total é 6% ao ano, e no ETF de distribuição 2% por ano é pago em dividendos (tributados a 28% e reinvestidos por ti). No de acumulação, tudo fica dentro do fundo.`},
    {t:'cmp',id:'c1',head:['Cenário','Valor final antes de imposto','Imposto total pago','Fica contigo'],rows:[
      ['Distribuição (28% nos dividendos e na venda)',_imp_e2(_imp_ad(20,.06,.02).dist.V),_imp_e2(_imp_ad(20,.06,.02).dist.tax),_imp_e2(_imp_ad(20,.06,.02).dist.net)],
      ['Acumulação (28% na venda)',_imp_e2(_imp_ad(20,.06,.02).acc.V),_imp_e2(_imp_ad(20,.06,.02).acc.tax),_imp_e2(_imp_ad(20,.06,.02).acc.net)],
      ['Acumulação, com os 30% de exclusão por 8 anos ou mais',_imp_e2(_imp_ad(20,.06,.02).acc30.V),_imp_e2(_imp_ad(20,.06,.02).acc30.tax),_imp_e2(_imp_ad(20,.06,.02).acc30.net)]],
      cap:'Simplificações: no cenário de distribuição não aplicámos a exclusão por detenção à venda final (ia baixar um pouco o imposto), e os dividendos reinvestidos entram no custo de compra. Os valores são ilustrativos, não uma previsão.'},
    {t:'p',id:'p2b',x:`O imposto, em percentagem, é o mesmo (28%), mas a acumulação paga <b>tudo no fim</b> e deixa o dinheiro a render por inteiro durante 20 anos. A diferença que vês na tabela (${_imp_e2(_imp_ad(20,.06,.02).acc.net-_imp_ad(20,.06,.02).dist.net)} entre acumulação e distribuição, antes de qualquer exclusão) vem desse efeito de adiamento. Este efeito é maior quanto mais longo o prazo e quanto maior o rendimento distribuído. A terceira linha mostra o bónus adicional da regra de 2024.`},
    {t:'h',id:'h3',x:'Quando a distribuição faz sentido'},
    {t:'ul',id:'u1',x:[
      'Quem precisa de rendimento regular (por exemplo, na reforma) pode preferir distribuição para receber sem vender unidades.',
      'Quem vive de um ETF de acumulação vende unidades quando precisa: o imposto incide só sobre o ganho dessas unidades, e és tu a decidir quando e quanto vender.',
      'A distribuição dá trabalho de declaração todos os anos (Anexo J, código E22); a acumulação dá trabalho só nos anos em que vendes.',
      'Com a acumulação, o imposto concentra-se nos anos em que vendes. É um valor grande de uma vez, por isso convém saber quanto vais pagar antes de vender.']},
    {t:'cmp',id:'c2',head:['','ETF de distribuição','ETF de acumulação'],rows:[
      ['Dividendos','Pagos na tua conta','Reinvestidos dentro do fundo'],
      ['Imposto durante a vida do investimento','28% sobre cada distribuição (Anexo J, E22)','Nenhum (nesta leitura da AT)'],
      ['Imposto na venda','28% sobre o ganho (Anexo J, G20)','28% sobre o ganho, com possível exclusão de 10% a 30% por tempo de detenção'],
      ['Reinvestimento','Tens de o fazer tu, já líquido de imposto','Automático e por inteiro']]},
    {t:'h',id:'h4',x:'Um caso real: o investidor que vive dos dividendos'},
    {t:'p',id:'p4',x:'Em 2020, muitas empresas cortaram dividendos durante a pandemia. Quem tinha ETFs de distribuição viu os pagamentos caírem; os ETFs de acumulação sentiram o mesmo corte, só que dentro do fundo, sem a «surpresa» na conta. Em ambos os casos o retorno total foi igual. A diferença foi na perceção: o dividendo que chega à conta parece «rendimento»; o reinvestido nunca se vê. O que importa para o retorno é o total, e o que importa para o imposto é <b>quando</b> é tributado.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que acumulação «não paga imposto». Paga, na venda, e pode ser muito dinheiro de uma vez.',
      'Achar que distribuição é «dinheiro grátis». É rendimento que já saiu do valor do ETF, e que ainda paga 28%.',
      'Comparar dois ETFs só pelo dividendo. O que conta é o retorno total, depois de custos e impostos.',
      'Comprar um ETF de distribuição, gastar o dividendo, e esquecer que o imposto foi calculado à mesma.',
      'Mudar de acumulação para distribuição (ou o contrário) vendendo: a venda é um facto tributável.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'pt',id:'pt1',pt:'sp500'},
    {t:'p',id:'p6',x:'Os dois ETFs da ficha acima são de <b>acumulação</b> e domiciliados na Irlanda: a tributação segue a lógica deste tema (mais-valia declarada no Anexo J quando vendes). Em corretoras estrangeiras, o cálculo é teu; em corretoras portuguesas que registem os títulos, confirma como tratam a retenção e a informação fiscal. Os ETFs americanos de distribuição ou acumulação (como o VOO ou o SPY) não se podem comprar cá, por não terem o documento europeu exigido (KID).'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Distribuição: dividendos pagos na conta, tributados a 28% todos os anos (Anexo J, quadro 8A, código E22).',
      'Acumulação: dividendos reinvestidos dentro do fundo; imposto só na venda (Anexo J, quadro 9.2A, código G20), nesta leitura do guia da AT.',
      'A taxa é a mesma; o que muda é o momento do pagamento, e o dinheiro continua a render por inteiro.',
      'Na venda de um ETF cotado detido mais de 2 anos, parte do ganho fica fora do imposto.',
      'O retorno total e os custos importam mais do que o tipo de ETF.']},
    {t:'fazve',id:'q1',ensina:['p1','c2'],q:'Um ETF de distribuição paga 20 € de dividendos numa posição tua. Quanto recebes líquido após 28% de imposto?',unit:'€',answer:14.4,tol:.01,why:'28% de 20 € = 5,60 €. Líquido: 14,40 €.'},
    {t:'fazve',id:'q2',ensina:['p1b','c2'],q:'Vendes, com 3 anos de detenção, um ETF de acumulação cotado com ganho de 5 000 € (sem outras operações). Quanto imposto pagas, tendo em conta a exclusão de 10% por detenção superior a 2 anos e inferior a 5?',unit:'€',answer:_imp_t(5000,0.1),tol:.01,why:`Ficam 90% de 5 000 € = 4 500 € a tributar. 4 500 × 28% = ${_imp_e2(_imp_t(5000,0.1))}.`},
    {t:'decide',id:'q3',ensina:['p1b','p2b'],label:'Decide',q:'Que vantagem fiscal tem, em geral, o ETF de acumulação para quem investe a longo prazo?',o:['Paga menos imposto no total','Não paga imposto nenhum','O imposto sobre o rendimento só é pago na venda, por isso o dinheiro continua a render por inteiro'],c:2,why:'A taxa é a mesma, mas o pagamento adia-se até à venda, o que deixa mais capital a trabalhar entretanto. E, com detenção longa, a mais-valia final pode beneficiar da exclusão de 10% a 30%.'},
    {t:'erro',id:'q4',ensina:['p1','c2'],label:'Encontra o erro',q:'Um amigo diz: «O ETF de acumulação não paga imposto nenhum, nem na venda.» Onde está o erro?',o:['Não há erro','Na venda há mais-valia tributada a 28% (Anexo J, G20, para fundos não residentes)','O imposto é pago todos os meses'],c:1,why:'Segundo o guia da AT, o resgate ou a venda de fundos não residentes gera mais-valia tributada a 28% (código G20, Anexo J). O imposto é adiado, não eliminado.'}
  ], src:[_AT_GUIA,_imp_43,_imp_L31,_imp_OF] },

{ id:'modelo3', topic:'impostos', o:7, title:'Declarar no IRS: Modelo 3, anexos G e J', mins:8,
  lead:'Os investimentos aparecem na declaração de IRS (Modelo 3) em anexos próprios. Saber qual usar, e que dados reunir antes, evita erros, atrasos e coimas.',
  blocks:[
    {t:'h',id:'h0',x:'Uma declaração com gavetas'},
    {t:'p',id:'p0',x:'Pensa na declaração de IRS como um armário com gavetas. A folha de rosto identifica-te e, depois, cada tipo de rendimento tem a sua gaveta, o <b>anexo</b>. Se não tens rendimentos desse tipo, a gaveta fica fechada. Um investidor português costuma usar, além das gavetas do trabalho, as dos rendimentos de capitais (juros, dividendos), das mais-valias, dos rendimentos do estrangeiro e, quando há PPR, a dos benefícios fiscais.'},
    {t:'h',id:'h1',x:'Que anexo usar, em cada caso'},
    {t:'cmp',id:'c1',head:['Anexo','Para quê','Exemplo'],rows:[
      ['A','Rendimentos do trabalho dependente e pensões','Salário, pensão'],
      ['E','Rendimentos de capitais obtidos em Portugal','Juros ou dividendos de entidades portuguesas, quando englobas'],
      ['F','Rendimentos prediais (categoria F)','Rendas de casas, rendimentos de fundos imobiliários nacionais'],
      ['G','Mais-valias e outros incrementos patrimoniais','Venda de ações ou ETFs a uma entidade portuguesa'],
      ['G1','Mais-valias excluídas de tributação','Criptoativos detidos há 365 dias ou mais'],
      ['H','Benefícios fiscais e deduções','Entregas para um PPR, despesas dedutíveis'],
      ['J','Rendimentos obtidos no estrangeiro','Dividendos e mais-valias numa corretora de outro país']],
      cap:'Fontes: Ofício-Circulado da AT n.º 20291, de 17/03/2026 (títulos dos anexos), e guia da AT de outubro de 2023. Há outros anexos (B, C, D) para atividade independente e outros casos.'},
    {t:'p',id:'p1',x:'A regra geral é: os residentes em Portugal declaram <b>todos</b> os rendimentos, obtidos cá ou lá fora (o guia da AT di-lo: o IRS incide «sobre a globalidade dos seus rendimentos, incluindo os obtidos no estrangeiro»). O que muda é o anexo. Para ações de empresas e fundos não residentes, a venda declara-se no <b>Anexo J</b>; para os restantes, no <b>Anexo G</b>.'},
    {t:'h',id:'h2',x:'Os quadros e códigos que a AT cita'},
    {t:'cmp',id:'c2',head:['O que declaras','Onde (guia da AT, outubro de 2023)'],rows:[
      ['Dividendos estrangeiros com retenção em Portugal','Anexo J, quadro 8A, código E10 (englobamento: quadro 8B, «SIM»)'],
      ['Dividendos estrangeiros sem retenção em Portugal','Anexo J, quadro 8A, código E11'],
      ['Juros de contas no estrangeiro (28%)','Anexo J, quadro 8A, código E21'],
      ['Distribuições de fundos/ETFs não residentes','Anexo J, quadro 8A, código E22'],
      ['Venda de ações de sociedades não residentes','Anexo J, quadro 9.2A (englobamento: quadro 9.2C)'],
      ['Resgate ou venda de fundos/ETFs não residentes','Anexo J, quadro 9.2A, código G20'],
      ['Venda de ações de empresas portuguesas','Anexo G, quadro 9; opção de englobar no quadro 15'],
      ['Contas bancárias no estrangeiro (IBAN e BIC)','Anexo J, quadro 11'],
      ['Criptoativos (menos de 365 dias / 365 dias ou mais)','Anexo G, quadro 18A / Anexo G1, quadro 7 (folheto da AT sobre criptoativos)']],
      cap:'Códigos e quadros mudam entre versões do Modelo 3. Estes são os que a AT indica nos documentos que consultámos.'},
    {t:'note',id:'n1',pending:true,x:'Os códigos E10, E11, E21, E22 e o quadro 11 vêm do guia da AT de outubro de 2023. O Ofício-Circulado de março de 2026 confirma, por seu lado, que o código G20 e o quadro 9.2A existem no Modelo 3 em vigor, mas não repete os outros. Antes de declarar, confirma cada código nas instruções do ano de entrega.'},
    {t:'h',id:'h3',x:'Reunir os dados: o exemplo de uma ficha de vendas'},
    {t:'p',id:'p3',x:'Cada venda tem de ser associada à compra correspondente. Uma folha simples, uma linha por venda, chega. Exemplo (valores de exemplo, comissões incluídas em «despesas»):'},
    {t:'cmp',id:'c3',head:['Ativo','Compra','Venda','Despesas','Ganho ou perda'],rows:[
      ['ETF A',_imp_e2(5000),_imp_e2(6400),_imp_e2(15),_imp_e2(6400-5000-15)],
      ['Ação B',_imp_e2(3000),_imp_e2(2500),_imp_e2(15),_imp_e2(2500-3000-15)],
      ['ETF C',_imp_e2(2000),_imp_e2(2300),_imp_e2(10),_imp_e2(2300-2000-10)],
      ['Saldo do ano','','','',_imp_e2((6400-5000-15)+(2500-3000-15)+(2300-2000-10))]],
      cap:'Imposto à taxa de 28% sobre o saldo positivo: '+_imp_e2(((6400-5000-15)+(2500-3000-15)+(2300-2000-10))*0.28)+'.'},
    {t:'ul',id:'u1',x:[
      'Guarda os <b>extratos e notas de execução</b> da corretora (preço de compra, venda, comissões e data). É com eles que calculas a mais-valia.',
      'Pede à corretora um relatório anual de operações, se tiver: poupa-te trabalho, mas confere os valores.',
      'Para ativos vendidos com mais de 2 anos de detenção, regista a <b>data de compra</b>: o tempo conta (tema «Mais-valias: quanto imposto pagas ao vender»).',
      'Guarda também o comprovativo de qualquer imposto retido no estrangeiro, para o crédito de imposto (tema «Dividendos e juros»).']},
    {t:'h',id:'h4',x:'Um caso real: o Modelo 3 de 2026'},
    {t:'p',id:'p4',x:'O Modelo 3 muda quase todos os anos. O deste ano (para os rendimentos de 2025) foi aprovado pela Portaria n.º 104/2026/1, de 5 de março, e explicado no Ofício-Circulado n.º 20291, de 17 de março de 2026. Entre as novidades, o quadro 9.2A do Anexo J passou a ter uma coluna onde indicas se a venda respeita a valores admitidos à negociação ou a partes de fundos abertos: é esse «Sim» que permite à AT aplicar o desconto por detenção de 2, 5 ou 8 anos. Ou seja, uma regra fiscal de 2024 só chegou ao formulário em 2026. Se preencheres tudo de memória do ano anterior, arriscas-te a perder o benefício.'},
    {t:'h',id:'h5',x:'Prazos e forma de entrega'},
    {t:'p',id:'p5',x:`A declaração entrega-se <b>exclusivamente por via eletrónica</b>, no Portal das Finanças, com o NIF e a senha ou com a Chave Móvel Digital (guia da AT). O prazo da entrega anual é de <b>1 de abril a 30 de junho</b> do ano seguinte ao dos rendimentos (art. 60.º do Código do IRS; para os rendimentos de 2025, o Ofício da AT confirma que termina a 30/06/2026). Quem tem rendimentos de fonte estrangeira com direito a crédito de imposto, e o montante ainda não está fixado no país da fonte, pode entregar até 31 de dezembro desse ano, se o comunicar à AT dentro do prazo normal. Mais pormenor no tema «Calendário fiscal do investidor: o que acontece em cada mês».`},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Escolher o anexo pela corretora e não pela entidade: o que conta é se o ativo ou o pagador é residente ou não.',
      'Não guardar os documentos. Sem preços e datas, não consegues calcular nem justificar o ganho.',
      'Usar códigos do ano anterior sem os conferir: o modelo muda.',
      'Esquecer-se das contas estrangeiras (IBAN e BIC no Anexo J, quadro 11).',
      'Deixar tudo para o último dia: os erros de último minuto são os mais caros.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p7',x:'Em Portugal, o Modelo 3 é o único formulário: a entrega faz-se no Portal das Finanças. Com bancos e corretoras portugueses, muitos rendimentos chegam já tratados (retenção a 28%). Com corretoras estrangeiras, o Anexo J é o teu. Antes de submeteres, relê com atenção o que preencheste.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'O Anexo G é para vendas a entidades portuguesas; o Anexo J para o estrangeiro; o Anexo E para capitais cá.',
      'Em corretoras estrangeiras, o cálculo e a declaração são teus: quadro 8A para dividendos, 9.2A para vendas.',
      'Guarda notas de execução, datas e comprovativos de imposto retido.',
      'O Modelo 3 muda todos os anos: confirma os códigos nas instruções do ano.',
      'Entrega: 1 de abril a 30 de junho, só por via eletrónica.']},
    {t:'decide',id:'q1',ensina:['c1','p1','c2'],label:'Decide',q:'Vendeste ETFs numa corretora de outro país da UE com lucro. Em que anexo declaras a mais-valia?',o:['Anexo E','Anexo J','Não declaras'],c:1,why:'Para entidades não residentes, os rendimentos obtidos no estrangeiro declaram-se no Anexo J (quadro 9.2A, código G20 para fundos e ETFs).'},
    {t:'decide',id:'q2',ensina:['u1'],label:'Decide',q:'Porque convém guardar as notas de execução da corretora?',o:['Para decorar a casa','Não é necessário guardar nada','Porque dão o preço, a data e as comissões de cada compra e venda, necessários para calcular a mais-valia'],c:2,why:'Sem esses dados não consegues calcular o ganho nem justificá-lo à Autoridade Tributária.'},
    {t:'fazve',id:'q3',ensina:['c3','p3'],q:'Na ficha de vendas do exemplo, qual é o saldo do ano (soma dos ganhos e perdas)?',unit:'€',answer:(6400-5000-15)+(2500-3000-15)+(2300-2000-10),tol:.01,why:`Ganhos e perdas: ${_imp_e2(6400-5000-15)} − ${_imp_e2(Math.abs(2500-3000-15))} + ${_imp_e2(2300-2000-10)} = ${_imp_e2((6400-5000-15)+(2500-3000-15)+(2300-2000-10))}.`},
    {t:'erro',id:'q4',ensina:['p5'],label:'Encontra o erro',q:'Um amigo diz: «Posso entregar o IRS em papel numa repartição, até 30 de junho.» Onde está o erro?',o:['Não há erro','A entrega é feita exclusivamente por via eletrónica, no Portal das Finanças','O prazo é até 31 de maio'],c:1,why:'O guia da AT indica que a declaração é entregue exclusivamente por transmissão eletrónica, com NIF e senha ou Chave Móvel Digital. O prazo anual é de 1 de abril a 30 de junho.'}
  ], src:[_AT_GUIA,_imp_OF,_imp_60,{l:'Portal das Finanças: Criptoativos, conceito fiscal e tributação',u:'https://info.portaldasfinancas.gov.pt/pt/apoio_contribuinte/Folhetos_informativos/Documents/Criptoativos.pdf'}] },

{ id:'calendario-fiscal', topic:'impostos', o:8, title:'Calendário fiscal do investidor: o que acontece em cada mês', mins:7,
  lead:'O IRS dos teus investimentos não é um momento: é um ano. Há datas que contam para o imposto, datas em que declaras e datas em que pagas ou recebes. Conhecer a ordem ajuda a decidir melhor, e evita passar o prazo.',
  blocks:[
    {t:'h',id:'h0',x:'Um ano em três tempos'},
    {t:'p',id:'p0',x:'Pensa num ano de IRS como uma viagem em três tempos. No <b>primeiro</b>, ao longo do ano civil (de 1 de janeiro a 31 de dezembro), as coisas acontecem: vendes, recebes dividendos, entregas dinheiro ao PPR. No <b>segundo</b>, no ano seguinte, declaras o que aconteceu. No <b>terceiro</b>, a AT calcula o imposto e pagas ou recebes. Os rendimentos de 2025 são declarados em 2026, os de 2026 em 2027, e assim sucessivamente.'},
    {t:'h',id:'h1',x:'Mês a mês'},
    {t:'cmp',id:'c1',head:['Quando','O que acontece','Base'],rows:[
      ['Ao longo do ano','As entidades que retêm IRS entregam-no ao Estado todos os meses («Pagamentos das importâncias retidas na fonte»)','Agenda Fiscal 2026'],
      ['Fevereiro','A Agenda Fiscal lista a «Declaração mod. 10» e a «Validação das faturas do ano anterior, no portal (e-fatura)»','Agenda Fiscal 2026'],
      ['Março','A AT publica o Modelo 3 e as instruções do ano (em 2026: Portaria n.º 104/2026/1, de 5 de março, e Ofício-Circulado de 17 de março)','Ofício-Circulado 20291/2026'],
      ['1 de abril a 30 de junho','Entrega da declaração Modelo 3 (rendimentos do ano anterior), por via eletrónica','Art. 60.º do CIRS'],
      ['Até 31 de julho','A AT conclui a liquidação (cálculo do imposto) das declarações entregues no prazo','Art. 77.º do CIRS'],
      ['Até 31 de agosto','Pagamento do imposto apurado, nas liquidações feitas no prazo de julho','Art. 97.º do CIRS'],
      ['30 de novembro','Prazo de liquidação nos restantes casos previstos no CIRS','Art. 77.º do CIRS'],
      ['Até 31 de dezembro','Pagamento nas liquidações do prazo de novembro; entrega prorrogada se esperas o crédito de imposto estrangeiro','Arts. 97.º e 60.º do CIRS']],
      cap:'Datas do ano de 2026 (rendimentos de 2025), verificadas em 17/11/2026. As datas legais (1 de abril a 30 de junho, 31 de julho, 31 de agosto) vêm do Código do IRS; cada ano a AT publica a Agenda Fiscal.'},
    {t:'note',id:'n1',pending:true,x:'O que cada entidade comunica à AT em fevereiro (a «Declaração mod. 10»), as datas de reembolso, e as datas de IMI, IMT e imposto do selo não ficaram confirmadas em fonte oficial para este tema. Consulta a Agenda Fiscal no Portal das Finanças.'},
    {t:'h',id:'h2',x:'O que fazer antes de 31 de dezembro'},
    {t:'p',id:'p2',x:'Como o saldo de mais-valias é <b>anual</b>, e o ano é o civil, 31 de dezembro é uma data com consequências. Uma venda feita a 30 de dezembro conta para este ano; a de 2 de janeiro conta para o seguinte. Quem quer realizar uma perda para a compensar com ganhos do mesmo ano, ou adiar um ganho para o ano seguinte, tem de decidir antes dessa data. O mesmo vale para o PPR: a dedução depende do montante aplicado <b>no ano</b> (art. 21.º do EBF). Nenhuma destas coisas se resolve em janeiro.'},
    {t:'p',id:'p2b',x:`Outra data que conta é a dos <b>365 dias</b>. Se compras ETFs a 10 de fevereiro de 2026, 365 dias depois é ${new Date(Date.UTC(2026,1,10)+365*864e5).toLocaleDateString('pt-PT',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'})}. Vender um dia antes, em vez de um dia depois, pode obrigar-te a englobar o ganho, se estiveres no último escalão (art. 72.º, n.º 14). Deixa sempre uma margem de segurança.`},
    {t:'note',id:'n2',pending:true,x:'A forma exata como a AT conta os 365 dias (se o dia da compra entra ou não na contagem) não ficou confirmada. Por isso, o exemplo acima mostra a data aproximada e recomendamos uma margem de alguns dias.'},
    {t:'h',id:'h3',x:'Os 91 dias para declarar'},
    {t:'p',id:'p3',x:`A janela de entrega da declaração, de 1 de abril a 30 de junho, tem ${(Date.UTC(2026,5,30)-Date.UTC(2026,3,1))/864e5+1} dias (incluindo os dois extremos). O melhor momento costuma ser quando já tens todos os documentos: os extratos anuais das corretoras e do banco, os comprovativos de imposto retido lá fora e o PPR de dezembro. A data limite não muda: 30 de junho.`},
    {t:'h',id:'h4',x:'Um caso real: o Modelo 3 que só chega em março'},
    {t:'p',id:'p4',x:'Em 2026, as instruções do novo Modelo 3 só foram explicadas pela AT em 17 de março, a duas semanas do arranque da entrega. Isto quer dizer que quem se prepara em janeiro com o formulário do ano anterior pode ter surpresas: códigos novos, colunas novas (como a das vendas de valores admitidos à negociação) e anexos alterados. Reunir os documentos cedo e deixar o preenchimento para depois de abril é uma boa regra.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Contar com o prazo do ano passado sem confirmar: o Código fixa 1 de abril a 30 de junho, mas as instruções mudam.',
      'Vender no dia 364 por falta de atenção, quando o 365.º dia mudava o regime.',
      'Pagar o PPR em janeiro a pensar que conta para o ano anterior: conta para o ano da entrega.',
      'Esquecer que, depois da liquidação, o pagamento tem prazo: até 31 de agosto, na regra geral.',
      'Não pedir à corretora, em janeiro, o relatório anual: é mais difícil em junho.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Tudo se faz no Portal das Finanças, com NIF e senha ou Chave Móvel Digital. O Código do IRS fixa os prazos gerais, e a Agenda Fiscal anual da AT lista as obrigações, mês a mês. Para os detalhes de cada passo, ver os temas «Declarar no IRS: Modelo 3, anexos G e J» e «Retenção na fonte».'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'O ano fiscal é o civil: 1 de janeiro a 31 de dezembro. O saldo de mais-valias fecha a 31 de dezembro.',
      'Declara-se no ano seguinte: 1 de abril a 30 de junho, por via eletrónica.',
      'A AT calcula até 31 de julho; o pagamento é até 31 de agosto (regra geral).',
      'Rendimentos estrangeiros com crédito de imposto por fixar podem ter entrega prorrogada até 31 de dezembro.',
      'O Modelo 3 muda todos os anos: confirma as instruções antes de preencher.']},
    {t:'fazve',id:'q1',ensina:['p3','c1'],q:'Quantos dias tem a janela de entrega da declaração de IRS, de 1 de abril a 30 de junho de 2026 (incluindo os dois extremos)?',unit:'dias',answer:(Date.UTC(2026,5,30)-Date.UTC(2026,3,1))/864e5+1,tol:.01,why:'Abril tem 30 dias, maio 31 e junho 30: 30 + 31 + 30 = 91 dias.'},
    {t:'decide',id:'q2',ensina:['c1','h1'],label:'Decide',q:'Quando termina, em regra, o prazo de entrega da declaração Modelo 3 dos rendimentos do ano anterior?',o:['31 de março','30 de junho','31 de dezembro'],c:1,why:'O artigo 60.º do Código do IRS fixa a entrega de 1 de abril a 30 de junho. Para rendimentos estrangeiros com crédito de imposto por fixar, pode ser até 31 de dezembro, se comunicado à AT no prazo normal.'},
    {t:'decide',id:'q3',ensina:['p2'],label:'Decide',q:'Queres que uma perda de uma ação conte para compensar um ganho deste ano. Até quando tens de vender?',o:['Até 31 de dezembro do mesmo ano','Até 30 de junho do ano seguinte','Até à entrega da declaração'],c:0,why:'O saldo de mais-valias é calculado por ano civil: só as vendas feitas até 31 de dezembro contam para o saldo desse ano.'},
    {t:'erro',id:'q4',ensina:['p2'],label:'Encontra o erro',q:'Um amigo diz: «Já estamos em janeiro, mas entrego 1 000 € no PPR e deduzo no IRS do ano passado.» Onde está o erro?',o:['Não há erro','A dedução depende do montante aplicado no ano: o que entregas em janeiro conta para o novo ano','O PPR não tem dedução'],c:1,why:'O artigo 21.º do EBF permite deduzir 20% do montante aplicado no ano (até aos limites por idade). O que entregas em janeiro conta para esse ano, não para o anterior.'}
  ], src:[_imp_60,_imp_AG,_imp_OF,{l:'Portal das Finanças: artigo 77.º do Código do IRS (prazos de liquidação)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs77.aspx'},{l:'Portal das Finanças: artigo 97.º do Código do IRS (prazos de pagamento)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs97.aspx'},_AT_72] },

{ id:'imposto-selo', topic:'impostos', o:9, title:'Imposto do selo', mins:7,
  lead:'Um imposto antigo que aparece em muitas situações. No investimento, importa sobretudo para as comissões, para os fundos, para a compra de imóveis e para as heranças e doações.',
  blocks:[
    {t:'h',id:'h0',x:'Uma «taxinha» em cima de quase tudo'},
    {t:'p',id:'p0',x:'O imposto do selo é como o carimbo que, antigamente, se punha nos documentos para os validar. Hoje é um imposto cobrado sobre atos e contratos, com uma lista de situações e de taxas: a <b>Tabela Geral do Imposto do Selo</b>. Cada linha da lista chama-se «verba» e tem o seu número. Para um investidor, o que interessa é saber em que verbas é que ele aparece, porque é um custo que se soma ao que já pagas.'},
    {t:'h',id:'h1',x:'As verbas que mais te podem tocar'},
    {t:'cmp',id:'c1',head:['Situação','Verba','Taxa'],rows:[
      ['Comissões e outras contraprestações por serviços financeiros','17.3.4','4%'],
      ['Aquisição onerosa ou por doação de imóveis','1.1','0,8%'],
      ['Aquisição gratuita de bens (heranças e doações)','1.2','10%, com isenção para cônjuge, unido de facto, descendentes e ascendentes'],
      ['Organismos de investimento coletivo que investem só em instrumentos monetários e depósitos','29.1','0,0025% por trimestre'],
      ['Outros organismos de investimento coletivo','29.2','0,0125% por trimestre'],
      ['Crédito (por prazo)','17.1','0,04% por mês (menos de 1 ano); 0,50% (1 ano ou mais); 0,60% (5 anos ou mais)']],
      cap:'Tabela Geral do Imposto do Selo, ' + _imp_V + '. A tabela tem muitas outras verbas e exceções.'},
    {t:'h',id:'h2',x:'Nas comissões: o custo escondido'},
    {t:'p',id:'p1',x:`Nas <b>comissões</b> de serviços financeiros, o imposto do selo é acrescentado ao custo de cada operação ou serviço. Uma comissão de ${_imp_e2(5)} custa ${_imp_e2(5*1.04)}: ${_imp_e2(5*0.04)} é imposto do selo. Parece pouco, mas soma-se: numa carteira que faz muitas operações, os 4% sobre as comissões acrescentam-se ao custo total. É por isso que, ao comparar corretoras e fundos, convém ver o custo com imposto e não só o preço de tabela.`},
    {t:'h',id:'h3',x:'Nos imóveis: 0,8% a somar à compra'},
    {t:'p',id:'p2',x:`A verba 1.1 aplica 0,8% à aquisição onerosa de imóveis. Numa casa de ${_imp_e2(200000)} (valor de exemplo), são ${_imp_e2(200000*0.008)} de imposto do selo, que se somam a outros impostos da compra. O imposto municipal sobre transmissões (IMT) é outro imposto, com as suas regras, e não está coberto aqui.`},
    {t:'h',id:'h4',x:'Em heranças e doações: o que a lei isenta'},
    {t:'p',id:'p3',x:`Nas <b>heranças e doações</b>, a verba 1.2 aplica 10% sobre o valor dos bens. O artigo 6.º do Código do Imposto do Selo isenta o cônjuge ou unido de facto, os descendentes e os ascendentes. Se os beneficiários forem outros (irmãos, amigos), aplica-se o imposto. Exemplo (valor de exemplo): um legado de ${_imp_e2(100000)} a um amigo paga ${_imp_e2(100000*0.1)}; o mesmo legado a um filho está isento. As doações de imóveis têm ainda a verba 1.1 (0,8%).`},
    {t:'p',id:'p3b',x:'A isenção do artigo 6.º, porém, não se aplica a instituições de crédito, sociedades financeiras, seguradoras e entidades equiparadas, quando o imposto seria um encargo seu.'},
    {t:'h',id:'h5',x:'Nos fundos: um custo dentro do fundo'},
    {t:'p',id:'p4',x:`A Tabela Geral tem ainda verbas para os organismos de investimento coletivo (verbas 29.1 e 29.2), com taxas trimestrais sobre o valor líquido. Em números (de exemplo): 0,0125% por trimestre num fundo de ${_imp_e2(1000000)} são ${_imp_e2(1000000*0.000125)} por trimestre, ${_imp_e2(1000000*0.000125*4)} por ano, o equivalente a ${_imp_pc(0.000125*4)} ao ano. É um custo pequeno, mas que existe, e que reduz o retorno do fundo.`},
    {t:'note',id:'n1',pending:true,x:'Não ficou confirmado em fonte oficial como as verbas 29.1 e 29.2 se aplicam aos ETFs domiciliados noutros países (por exemplo, na Irlanda), nem se o custo é suportado pelo fundo ou pelos participantes. Há também outras verbas e exceções, incluindo decisões que afastam o imposto sobre certas comissões de fundos. Para um caso concreto, consulta a Tabela Geral no Portal das Finanças.'},
    {t:'h',id:'h6',x:'Um caso do dia a dia (hipotético)'},
    {t:'p',id:'p5',x:`O Duarte compra e vende ETFs 20 vezes por ano, e a corretora cobra ${_imp_e2(3)} por operação. Parece barato: ${_imp_e2(3*20)} por ano. Com o imposto do selo (4%), são ${_imp_e2(3*20*1.04)}. Se, em vez disso, comprasse uma vez por mês durante um ano (12 operações), pagaria ${_imp_e2(3*12*1.04)}. Nada disto é grave, mas mostra que cada operação tem um custo total que inclui este imposto, e que o investimento regular e simples costuma sair mais barato do que mexer muito.`},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Ignorar o selo ao comparar custos: uma comissão de 5 € custa 5,20 €.',
      'Achar que a isenção em heranças vale para todos: só cônjuge ou unido de facto, descendentes e ascendentes.',
      'Esquecer que o imposto do selo na compra de um imóvel (0,8%) é diferente do IMT.',
      'Confundir imposto do selo com IRS: são impostos diferentes, com regras e declarações diferentes.']},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p6',x:'O imposto do selo é cobrado em Portugal sobre os atos e contratos aqui realizados, e a tabela está no Portal das Finanças. Em muitos casos quem cobra é a própria entidade (banco, corretora, notário) e tu nem o vês como linha separada. Verifica sempre a nota de custos da corretora: se tem «imposto do selo» discriminado, é esse.'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'O imposto do selo incide sobre atos e contratos listados na Tabela Geral, cada um numa «verba».',
      'Comissões de serviços financeiros: 4%. Compra de imóveis: 0,8%.',
      'Heranças e doações: 10%, com isenção para cônjuge ou unido de facto, descendentes e ascendentes.',
      'Há verbas para fundos de investimento (29.1 e 29.2): confirma como se aplicam ao teu caso.',
      'É um custo que se soma ao preço: inclui-o nas contas.']},
    {t:'decide',id:'q1',ensina:['c1','p1'],label:'Decide',q:'Qual é, em regra, a taxa de imposto do selo sobre as comissões de serviços financeiros?',o:['4%','0,8%','10%'],c:0,why:'A verba 17.3.4 da Tabela Geral aplica 4% às comissões e contraprestações por serviços financeiros.'},
    {t:'decide',id:'q2',ensina:['p3','c1'],label:'Decide',q:'Um pai doa um imóvel a um filho. Que imposto do selo se aplica?',o:['10% sobre o valor','Nenhum','0,8% sobre o valor do imóvel (a verba de 10% não se aplica entre familiares próximos)'],c:2,why:'A verba 1.2 (10%) tem isenção para descendentes, mas a verba 1.1 (0,8%) aplica-se às doações de imóveis.'},
    {t:'fazve',id:'q3',ensina:['p1','c1'],q:'A corretora cobra 5 € de comissão numa operação. Quanto pagas no total, com imposto do selo de 4% sobre a comissão?',unit:'€',answer:5.2,tol:.01,why:'4% de 5 € = 0,20 €. Total: 5,20 €.'},
    {t:'erro',id:'q4',ensina:['p3','p3b'],label:'Encontra o erro',q:'Um amigo diz: «Deixei 50 000 € a um primo e, como é família, não paga imposto do selo.» Onde está o erro?',o:['Não há erro','A isenção só abrange cônjuge ou unido de facto, descendentes e ascendentes: um primo paga 10%','As heranças nunca pagam imposto do selo'],c:1,why:'O artigo 6.º do Código do Imposto do Selo isenta cônjuge ou unido de facto, descendentes e ascendentes. Um primo não está na lista e paga os 10% da verba 1.2.'}
  ], src:[_imp_TGIS,{l:'Portal das Finanças: Imposto do Selo, artigo 6.º (isenções)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/selo/Pages/selo6.aspx'}] },

{ id:'ppr-fiscal', topic:'impostos', o:10, title:'PPR e benefícios fiscais', mins:8,
  lead:'O PPR dá uma dedução à coleta do IRS quando entregas dinheiro, e uma tributação reduzida quando o levantas nas condições da lei. Fora delas, o benefício perde-se e paga-se mais. Perceber os dois lados evita surpresas.',
  blocks:[
    {t:'h',id:'h0',x:'Um desconto com uma condição'},
    {t:'p',id:'p0',x:'Pensa num cupão de desconto que só é válido se não fores buscar o dinheiro antes de tempo. O <b>PPR</b> (plano de poupança-reforma) funciona assim: o Estado dá-te um desconto no IRS quando entregas dinheiro, e espera que o deixes lá para a reforma ou, pelo menos, durante um período longo. Se o levantares fora das situações previstas, o desconto perde-se, e com um acréscimo.'},
    {t:'h',id:'h1',x:'A entrada: a dedução à coleta'},
    {t:'p',id:'p1',x:'A dedução é <b>à coleta</b>: reduz o imposto, não a base. É de <b>20%</b> do valor aplicado no ano, com um limite que depende da tua idade a 1 de janeiro desse ano (Estatuto dos Benefícios Fiscais, art. 21.º, ' + _imp_V + ').'},
    {t:'cmp',id:'c1',head:['Idade a 1 de janeiro','Limite da dedução'],rows:[['Menos de 35 anos','400 €'],['De 35 a 50 anos','350 €'],['Mais de 50 anos','300 €']],cap:'EBF, art. 21.º. O limite é por sujeito passivo, não por família.'},
    {t:'p',id:'p2',x:'O limite aplica-se <b>por sujeito passivo</b>: nos casais, cada um dos cônjuges tem o seu. Para o aproveitares por inteiro precisas de coleta suficiente; se o teu IRS a pagar for baixo, a dedução pode não ser usada na totalidade. Os valores aplicados depois da passagem à reforma já não são dedutíveis.'},
    {t:'p',id:'p2b',x:`Vê o que isto significa em euros. Para ter a dedução máxima de ${_imp_e2(400)} (quem tem menos de 35 anos), tens de aplicar ${_imp_e2(400/0.2)} (porque 20% de ${_imp_e2(2000)} são ${_imp_e2(400)}). Acima disso, mais entregas não dão mais dedução: o benefício tem teto. Para quem tem mais de 50 anos, o teto de ${_imp_e2(300)} atinge-se com ${_imp_e2(300/0.2)}.`},
    {t:'h',id:'h2',x:'A saída: o que acontece ao levantar'},
    {t:'p',id:'p3',x:'O Estatuto dos Benefícios Fiscais distingue três situações. Primeiro, o <b>resgate nas condições da lei</b>: o dinheiro só pode ser movimentado sem perder o benefício decorridos 5 anos da entrega e se se verificar uma das situações previstas (o guia da AT de outubro de 2023 lista a reforma por velhice, o desemprego de longa duração, a incapacidade permanente, a doença grave, a idade de 60 anos, o ensino profissional ou superior, e o pagamento de prestações de crédito à habitação própria e permanente).'},
    {t:'ul',id:'u1',x:[
      '<b>Em prestações regulares e periódicas</b>: seguem as regras da categoria H do IRS (como uma pensão), com retenção na fonte como pagamento por conta.',
      '<b>Em reembolso total ou parcial</b> (até 10 anos, se em prestações): só o rendimento é tributado; a matéria coletável é <b>2/5 do rendimento</b>, tributada à taxa especial de <b>20%</b> (com opção pelo englobamento).',
      '<b>Fora das condições da lei</b>: o rendimento é tributado à taxa de <b>21,5%</b>, e as importâncias deduzidas são acrescidas à coleta do IRS, <b>majoradas em 10% por cada ano ou fração</b> desde a dedução. Se pelo menos 35% das entregas foram feitas na primeira metade da vigência do plano, aplicam-se as frações 4/5 (entre 5 e 8 anos) ou 2/5 (depois dos 8 anos) ao rendimento.']},
    {t:'p',id:'p3b',x:`<b>Um exemplo (valores de exemplo)</b>: entregas ao longo do tempo de ${_imp_e2(20000)}; no fim, o plano vale ${_imp_e2(28000)}, ou seja, rendimento de ${_imp_e2(8000)}. No resgate nas condições da lei: 2/5 de ${_imp_e2(8000)} = ${_imp_e2(8000*0.4)}, a 20% = <b>${_imp_e2(8000*0.4*0.2)}</b> de imposto, o que equivale a ${_imp_pc(0.4*0.2)} do rendimento. Fora das condições: 21,5% de ${_imp_e2(8000)} = <b>${_imp_e2(8000*0.215)}</b>, mais a devolução das deduções com a majoração. Num depósito, os mesmos ${_imp_e2(8000)} de juros pagariam 28% = ${_imp_e2(8000*0.28)}.`},
    {t:'p',id:'p3c',x:`A <b>majoração</b> também pesa. Se tinhas deduzido ${_imp_e2(400)} e a lei contar 3 «anos ou frações» desde a dedução (valor de exemplo), o acréscimo à coleta do IRS é ${_imp_e2(400)} × 130% = ${_imp_e2(400*1.3)}. A entrega que parecia vantajosa tornou-se um custo.`},
    {t:'note',id:'n1',pending:true,x:'A lista exata das situações em que o resgate é permitido sem perder o benefício vem do guia da AT de outubro de 2023 (a lei que a define remete-se, no EBF, para «situações definidas na lei»). Confirma a lista em vigor e como se conta «cada ano ou fração» antes de levantares. As regras do guia também previram condições especiais temporárias em 2022 e 2023, já terminadas.'},
    {t:'h',id:'h3',x:'Um caso real: a lei de 2024 e os produtos pan-europeus'},
    {t:'p',id:'p4',x:'A Lei n.º 31/2024, de 28 de junho, alterou o artigo 21.º do EBF e acrescentou-lhe um número (o n.º 11) sobre produtos pan-europeus de poupança-reforma. Esta é uma das várias medidas de 2024 para o mercado de capitais. O que se tira dela é que o enquadramento do PPR é <b>vivo</b>: a lei mudou há pouco, e vai continuar a mudar. Confirma sempre o artigo 21.º do EBF antes de decidires.'},
    {t:'h',id:'h4',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Aplicar mais do que o necessário para atingir o teto da dedução, pensando que há mais benefício.',
      'Levantar antes de 5 anos, ou fora das situações previstas, sem contar com a devolução do benefício e a majoração de 10% por ano.',
      'Ignorar que a dedução é à coleta: sem IRS a pagar, parte do benefício perde-se.',
      'Escolher o PPR só pelo benefício fiscal, sem ver custos, risco e investimentos dentro do plano.',
      'Esquecer que o limite depende da idade a 1 de janeiro, não da idade no dia da entrega.']},
    {t:'h',id:'h5',x:'Em Portugal'},
    {t:'p',id:'p5',x:'Os PPR são produtos portugueses, regidos pelo Estatuto dos Benefícios Fiscais, e quem os oferece são, em regra, bancos, seguradoras e gestoras de fundos: pergunta-lhes quais têm. A comparação entre PPR e investir por conta própria (por exemplo, em ETFs: tema «ETFs de acumulação e de distribuição») deve incluir comissões, risco, liquidez e o período de imobilização, além do benefício fiscal.'},
    {t:'h',id:'h6',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Dedução à coleta de 20% do valor aplicado, com teto de 400, 350 ou 300 € consoante a idade a 1 de janeiro.',
      'Por sujeito passivo, e só enquanto houver IRS a pagar.',
      'Levantamento nas condições da lei: só 2/5 do rendimento é tributado, a 20%.',
      'Levantamento fora das condições: 21,5% sobre o rendimento, e as deduções voltam à coleta com +10% por ano ou fração.',
      'Antes de resgatar, confirma a lista de situações permitidas e a contagem dos anos.']},
    {t:'fazve',id:'q1',ensina:['p1','c1'],q:'Tens 52 anos e aplicas 1 000 € num PPR. Quanto deduzes à coleta do IRS?',unit:'€',answer:200,tol:.01,why:'20% de 1 000 € = 200 €, que está abaixo do limite de 300 € para quem tem mais de 50 anos. Dedução: 200 €.'},
    {t:'fazve',id:'q2',ensina:['p3','u1','p3b'],q:'Um PPR rendeu 8 000 € e levantas tudo nas condições da lei. O rendimento é tributado em 2/5, à taxa de 20%. Quanto imposto pagas?',unit:'€',answer:8000*0.4*0.2,tol:.01,why:`2/5 de 8 000 € = ${_imp_e2(3200)}. 20% de ${_imp_e2(3200)} = ${_imp_e2(640)}.`},
    {t:'decide',id:'q3',ensina:['p2'],label:'Decide',q:'O teu IRS a pagar este ano é de 100 €. Aplicas 2 000 € num PPR (dedução possível: 350 €). O que acontece?',o:['A dedução é aplicada na totalidade e recebes a diferença','A dedução nunca se aplica','A dedução é feita à coleta, por isso só podes aproveitar até ao imposto que tiveres a pagar'],c:2,why:'A dedução reduz o imposto a pagar, não gera valor além dele. Sem coleta suficiente, parte do benefício não é aproveitada.'},
    {t:'erro',id:'q4',ensina:['u1','p3c'],label:'Encontra o erro',q:'Um amigo diz: «Levanto o PPR ao fim de 3 anos, sem estar na reforma nem em nenhuma situação especial. Pago só os 20% sobre 2/5 do rendimento.» Onde está o erro?',o:['Não há erro','Fora das situações previstas, aplica-se 21,5% ao rendimento e as deduções voltam à coleta com +10% por ano ou fração','O PPR nunca pode ser levantado'],c:1,why:'O regime de 2/5 a 20% é para o resgate nas condições da lei. Antes de 5 anos, ou sem uma das situações previstas, o benefício perde-se: o rendimento paga 21,5% e as deduções voltam à coleta majoradas.'}
  ], src:[{l:'Portal das Finanças: Estatuto dos Benefícios Fiscais, artigo 21.º',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/bf_rep/Pages/ebf-artigo-21-ordm-.aspx'},_AT_GUIA,{l:'Portal das Finanças: IRS, deduções e benefícios fiscais (folheto 2025)',u:'https://info.portaldasfinancas.gov.pt/pt/apoio_contribuinte/Folhetos_informativos/Documents/IRS_deducoes_2025.pdf'},_imp_L31] },

{ id:'imoveis-fiscal', topic:'impostos', o:11, title:'Rendimentos de imóveis: rendas (categoria F) e mais-valias de imóveis', mins:9,
  lead:'Uma casa pode render de duas formas: todos os meses, em rendas, e uma vez, quando a vendes com ganho. Cada uma tem o seu imposto e as suas regras. Aqui vês o mecanismo, com contas de exemplo; os valores que mudam ficam com a AT.',
  blocks:[
    {t:'h',id:'h0',x:'A renda e o ganho: duas torneiras'},
    {t:'p',id:'p0',x:'Pensa numa casa como um reservatório com duas torneiras. Uma pinga todos os meses: a renda. A outra só abre quando vendes: o ganho (se vendeste mais caro do que compraste). O IRS trata-as de forma diferente. A renda é um <b>rendimento predial</b> (categoria F); o ganho da venda é uma <b>mais-valia</b> (categoria G, a mesma de ações e ETFs, mas com regras próprias para imóveis). Neste tema vês as duas, só no plano do IRS: IMI, IMT e AIMI são outros impostos, e não estão cobertos aqui.'},
    {t:'h',id:'h1',x:'Rendas: o que é tributado'},
    {t:'p',id:'p1',x:'O IRS incide sobre as rendas recebidas, <b>menos as despesas</b> que a lei permite deduzir. Segundo o artigo 41.º do Código do IRS, deduzem-se os gastos pagos para obter ou garantir a renda de cada prédio (por exemplo, seguros de renda e despesas de condomínio), as obras de conservação e manutenção (em certas condições) e, no ano em que o rendimento é tributado, o IMI e o imposto do selo do prédio. Ficam de fora os gastos financeiros (juros do crédito), as depreciações, o mobiliário, os eletrodomésticos e o adicional ao IMI. É preciso prova documental de tudo.'},
    {t:'p',id:'p1b',x:'Sobre o rendimento líquido aplica-se uma <b>taxa autónoma</b>: <b>25%</b> no arrendamento habitacional e <b>28%</b> nos restantes rendimentos prediais (art. 72.º, n.os 1 e 2). Nos contratos de arrendamento para habitação permanente, a taxa baixa com a duração do contrato: menos <b>10 pontos percentuais</b> se o contrato tem entre 5 e menos de 10 anos, <b>15</b> pontos se tem entre 10 e menos de 20 anos, <b>20</b> pontos se tem 20 anos ou mais. Cada renovação de igual duração dá ainda mais 2 pontos de redução, dentro de um limite que o artigo fixa. Se o contrato cessar antes do prazo por motivo imputável ao senhorio, a redução perde-se.'},
    {t:'p',id:'p1c',x:'Há ainda a regra mais recente. O Decreto-Lei n.º 97/2026, de 20 de maio, pôs no Estatuto dos Benefícios Fiscais o artigo 45.º-C: a taxa autónoma dos rendimentos prediais de contratos de arrendamento para habitação, cuja renda mensal <b>não exceda 2,5 vezes a retribuição mínima mensal de 2026</b> (valor atualizável por portaria), e auferidos <b>até 31 de dezembro de 2029</b>, é de <b>10%</b>, «salvo quando seja aplicável uma taxa mais favorável». Produz efeitos desde 1 de janeiro de 2026.'},
    {t:'cmp',id:'c1',head:['Situação','Taxa autónoma','Imposto sobre ' + _imp_e2(_imp_im.liq) + ' de rendimento líquido'],rows:[
      ['Arrendamento habitacional, regra geral','25%',_imp_e2(_imp_im.liq*0.25)],
      ['Contrato de 5 a menos de 10 anos (menos 10 pontos)','15%',_imp_e2(_imp_im.liq*0.15)],
      ['Contrato de 10 a menos de 20 anos (menos 15 pontos)','10%',_imp_e2(_imp_im.liq*0.10)],
      ['Contrato de 20 anos ou mais (menos 20 pontos)','5%',_imp_e2(_imp_im.liq*0.05)],
      ['Renda moderada (art. 45.º-C do EBF), até 2029','10%, ou mais favorável',_imp_e2(_imp_im.liq*0.10)],
      ['Outros rendimentos prediais (não habitacionais)','28%',_imp_e2(_imp_im.liq*0.28)]],
      cap:`Exemplo: renda de ${_imp_e2(_imp_im.renda)} por mês, ${_imp_e2(_imp_im.rendaAno)} por ano, com ${_imp_e2(_imp_im.desp)} de despesas dedutíveis: rendimento líquido de ${_imp_e2(_imp_im.liq)}. As taxas das linhas 2 a 4 têm condições adicionais (por exemplo, limites de renda); confirma no artigo 72.º.`},
    {t:'note',id:'n0',pending:true,x:'Duas coisas não ficaram confirmadas em fonte oficial para este tema: a opção de englobar as rendas em vez da taxa autónoma (e quando compensa) e como a taxa de 10% das rendas moderadas se conjuga com as reduções por duração do contrato. Confirma no artigo 22.º e no artigo 72.º do Código do IRS, nas instruções do Anexo F do Modelo 3, ou com um contabilista.'},
    {t:'p',id:'p1d',x:'Quando quem paga a renda é uma entidade com contabilidade organizada (uma empresa, por exemplo), o artigo 101.º obriga-a a reter 25% (ou 10%, nos casos do artigo 45.º-C do EBF). As rendas declaram-se no <b>Anexo F</b> do Modelo 3. Se o inquilino é um particular, a obrigação de retenção não ficou esclarecida nas fontes que consultámos: pergunta ao Portal das Finanças ou a um contabilista.'},
    {t:'h',id:'h2',x:'Vender a casa: a mais-valia'},
    {t:'p',id:'p2',x:`Quando vendes um imóvel, o ganho calcula-se como nas ações, com mais algumas peças. Parte-se do valor de venda e subtrai-se: o valor de compra, <b>corrigido por coeficientes de desvalorização da moeda</b> se tiverem passado mais de 24 meses (art. 50.º, publicados por portaria); as <b>obras</b> que aumentaram o valor do imóvel, documentadas e feitas nos 12 anos anteriores à venda (art. 51.º); e as <b>despesas necessárias e efetivamente suportadas</b> na compra e na venda, comprovadas.`},
    {t:'p',id:'p2b',x:`<b>E depois só metade conta.</b> Para os imóveis, o artigo 43.º, n.º 2, diz que o saldo da mais-valia é considerado em apenas <b>50%</b>, salvo se o imóvel recebeu um apoio público não reembolsável acima de 30% do valor patrimonial tributário e é vendido dentro de 10 anos (nesse caso, conta por inteiro). Como não aparece na lista de taxas especiais do artigo 72.º (a lista refere outras alíneas do artigo 10.º, não a das vendas de imóveis), a parte que conta <b>entra no englobamento</b>: soma-se ao resto do teu rendimento e paga pelas taxas progressivas do IRS. O guia da AT diz o mesmo dos ganhos com fundos de investimento imobiliário: englobamento obrigatório, com apenas 50% do saldo a contar.`},
    {t:'p',id:'p2c',x:`Um exemplo (valores de exemplo, sem correção monetária, com tudo comprovado): compraste por ${_imp_e2(_imp_im.comp)}, vendeste por ${_imp_e2(_imp_im.real)}, fizeste obras de ${_imp_e2(_imp_im.obras)} e pagaste ${_imp_e2(_imp_im.dsp)} de despesas de compra e venda. Ganho = ${_imp_e2(_imp_im.real)} − ${_imp_e2(_imp_im.comp)} − ${_imp_e2(_imp_im.obras)} − ${_imp_e2(_imp_im.dsp)} = ${_imp_e2(_imp_im.ganho)}. Conta 50%: ${_imp_e2(_imp_im.cont)} a somar ao teu rendimento. Com os escalões <b>inventados</b> do tema «Englobamento: quando compensa» e um rendimento de ${_imp_e2(20000)}, o imposto extra seria ${_imp_e2(_imp_marg(20000,_imp_im.cont))}.`},
    {t:'h',id:'h3',x:'Não pagar imposto sobre a venda: o reinvestimento'},
    {t:'p',id:'p3',x:'O artigo 10.º do Código do IRS exclui de tributação o ganho da venda da <b>habitação própria e permanente</b> se o valor de realização (deduzido do crédito amortizado) for reinvestido noutra casa, em terreno para construção, ou em obras de ampliação ou melhoria. O reinvestimento tem de ser feito em Portugal ou noutro país da UE ou do EEE com troca de informações fiscais, <b>entre os 24 meses anteriores e os 36 meses posteriores</b> à venda, a casa vendida tem de ter sido o teu domicílio fiscal nos 12 meses anteriores, e tens de manifestar a intenção de reinvestir na declaração do ano da venda. O benefício perde-se, entre outros casos, se a nova casa não for ocupada ou registada nos prazos que o artigo prevê.'},
    {t:'p',id:'p3b',x:`No <b>reinvestimento parcial</b>, o benefício respeita só à parte proporcional do ganho. No exemplo anterior, se reinvestires ${_imp_e2(_imp_im.reinv)} dos ${_imp_e2(_imp_im.real)}, ficam excluídos ${_imp_e2(_imp_im.excl)} do ganho (metade) e os outros ${_imp_e2(_imp_im.rest)} contam; destes, só 50% entra no englobamento: ${_imp_e2(_imp_im.contRest)}.`},
    {t:'p',id:'p3c',x:'Há duas variantes mais. O Decreto-Lei n.º 97/2026 alargou a exclusão ao reinvestimento em imóveis destinados a <b>arrendamento habitacional com renda moderada</b> (limites do mesmo decreto), para vendas feitas entre 1 de janeiro de 2026 e 31 de dezembro de 2029, com prazos de arrendamento a cumprir. E, para quem está reformado ou tem 65 anos ou mais (o próprio ou o cônjuge), o artigo 10.º permite reinvestir em seguros de vida, fundos de pensões, regime público de capitalização ou PPR (e, desde 2024, em produtos individuais de poupança pan-europeus), dentro de um prazo curto e com limites aos levantamentos.'},
    {t:'h',id:'h4',x:'Um caso real: as medidas de habitação de 2026'},
    {t:'p',id:'p4',x:'Em maio de 2026, o Decreto-Lei n.º 97/2026 juntou num só diploma medidas que mexem com o IVA, o IMT, o IRS e os benefícios fiscais, todas orientadas para aumentar a oferta de casas, em especial de arrendamento a renda moderada. Duas delas vimos acima: a taxa de 10% nas rendas moderadas e a exclusão de mais-valias reinvestidas em arrendamento acessível. Moral prática: a fiscalidade dos imóveis é a que mais muda, e muitas medidas têm prazo (aqui, 31 de dezembro de 2029). Antes de uma decisão grande, confirma se a medida ainda está em vigor.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Deduzir despesas sem prova: o Código exige comprovação documental.',
      'Deduzir juros do crédito à habitação nas rendas: os gastos financeiros não são dedutíveis na categoria F.',
      'Esquecer-se de manifestar a intenção de reinvestir na declaração do ano da venda: é uma condição do artigo 10.º.',
      'Contar o reinvestimento do valor total quando só reinvestiste parte: o benefício é proporcional.',
      'Ignorar que as obras só contam se forem documentadas e dos últimos 12 anos.',
      'Pensar que a mais-valia da casa paga 28% como as ações: segue o englobamento, com 50% do saldo.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Tudo isto é fiscalidade portuguesa e aplica-se a imóveis em Portugal ou a residentes fiscais em Portugal. Para fundos de investimento imobiliário nacionais, o guia da AT diz que as distribuições são rendimentos prediais (categoria F), com retenção de 28% a título definitivo e opção de englobar no Anexo F, e que a venda ou o resgate das unidades dá uma mais-valia que se declara no Anexo G. IMT, IMI e AIMI (os impostos da compra e da posse) não ficaram confirmados aqui.'},
    {t:'note',id:'n1',pending:true,x:'IMT, IMI e AIMI (taxas, isenções e datas de pagamento) não estão cobertos neste tema nem foram confirmados em fonte oficial. Consulta o Portal das Finanças. Nem é conselho fiscal: para a venda ou arrendamento concretos, fala com um contabilista.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Rendas (categoria F): taxa autónoma sobre o rendimento líquido, 25% no arrendamento habitacional, 28% nos outros, menos 10 a 20 pontos em contratos longos.',
      'Rendas moderadas até 2029: 10%, segundo o artigo 45.º-C do EBF.',
      'Mais-valias de imóveis: só 50% do saldo conta, e entra no englobamento.',
      'Obras (12 anos) e despesas comprovadas reduzem o ganho; a compra corrige-se por coeficientes passados 24 meses.',
      'Reinvestir o valor na habitação própria e permanente (24 meses antes a 36 depois) exclui o ganho, proporcionalmente ao reinvestido.']},
    {t:'fazve',id:'q1',ensina:['p1','p1b','c1'],q:'Recebes 600 € de renda por mês, durante 12 meses, num contrato habitacional com taxa autónoma de 25%, e tens 1 800 € de despesas dedutíveis comprovadas. Quanto imposto de categoria F pagas?',unit:'€',answer:_imp_im.liq*0.25,tol:.01,why:`Rendimento líquido = ${_imp_e2(_imp_im.rendaAno)} − ${_imp_e2(_imp_im.desp)} = ${_imp_e2(_imp_im.liq)}. 25% de ${_imp_e2(_imp_im.liq)} = ${_imp_e2(_imp_im.liq*0.25)}.`},
    {t:'fazve',id:'q2',ensina:['p2','p2b','p2c'],q:'Compraste um imóvel por 150 000 €, vendeste-o por 200 000 €, fizeste 10 000 € de obras documentadas e pagaste 2 000 € de despesas (sem correção monetária). Que valor entra no englobamento, sabendo que só 50% do saldo conta?',unit:'€',answer:_imp_im.cont,tol:.01,why:`Ganho = ${_imp_e2(_imp_im.real)} − ${_imp_e2(_imp_im.comp)} − ${_imp_e2(_imp_im.obras)} − ${_imp_e2(_imp_im.dsp)} = ${_imp_e2(_imp_im.ganho)}. 50% = ${_imp_e2(_imp_im.cont)}.`},
    {t:'fazve',id:'q3',ensina:['p3','p3b'],q:'No exemplo anterior (ganho de 38 000 €, venda por 200 000 €), reinvestes 100 000 € na nova habitação própria e permanente. Que valor entra no englobamento?',unit:'€',answer:_imp_im.contRest,tol:.01,why:`Ficam excluídos ${_imp_e2(_imp_im.excl)} (100 000/200 000 do ganho). Restam ${_imp_e2(_imp_im.rest)}, dos quais só 50% contam: ${_imp_e2(_imp_im.contRest)}.`},
    {t:'decide',id:'q4',ensina:['p3'],label:'Decide',q:'Vendeste a tua habitação própria e permanente e queres que o ganho seja excluído de tributação. Em que período tens de reinvestir o valor numa nova casa?',o:['Só nos 12 meses seguintes à venda','Entre 24 meses antes e 36 meses depois da venda','Só até 31 de dezembro do ano da venda'],c:1,why:'O artigo 10.º, n.º 5, do Código do IRS prevê o reinvestimento entre os 24 meses anteriores e os 36 meses posteriores à data da venda, e a declaração da intenção de reinvestir no ano da venda.'},
    {t:'erro',id:'q5',ensina:['p2b','p2c'],label:'Encontra o erro',q:'Um amigo diz: «Vendi a casa com lucro e tenho de pagar 28% sobre o ganho todo, como nas ações.» Onde está o erro?',o:['Não há erro','Nos imóveis só 50% do saldo conta e entra no englobamento, não há taxa especial de 28%','Os imóveis nunca pagam imposto'],c:1,why:'O artigo 43.º, n.º 2, considera só 50% do saldo, e as vendas de imóveis não estão na lista de taxas especiais do artigo 72.º: a parte que conta entra no englobamento.'}
  ], src:[_AT_72,_imp_43,_imp_10,{l:'Portal das Finanças: artigo 41.º do Código do IRS (despesas na categoria F)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs41.aspx'},{l:'Portal das Finanças: artigo 50.º do Código do IRS (valor de aquisição)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs50.aspx'},{l:'Portal das Finanças: artigo 51.º do Código do IRS',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs51.aspx'},{l:'Portal das Finanças: artigo 101.º do Código do IRS (retenção)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs101.aspx'},_imp_DL97,_AT_GUIA] },

{ id:'cripto-irs', topic:'impostos', o:12, title:'Criptoativos e IRS', mins:8,
  lead:'Em Portugal, os ganhos com criptoativos têm uma regra própria que depende do tempo que os tiveste: detidos 365 dias ou mais, ficam fora de tributação; menos, pagam 28%. Trocar uma cripto por outra não gera imposto, mas converter em euros pode.',
  blocks:[
    {t:'h',id:'h0',x:'Uma coleção que só se tributa quando se converte'},
    {t:'p',id:'p0',x:'Imagina que colecionas cromos raros e trocas uns por outros com amigos. Enquanto os trocas por outros cromos, ninguém pergunta quanto ganhaste. Só quando vendes por euros se vê o ganho. Com as criptomoedas, o IRS português funciona de forma parecida. A lei foi escrita para isso: a Lei n.º 24-D/2022, de 30 de dezembro, introduziu expressamente no Código do IRS o enquadramento dos rendimentos de criptoativos. Um <b>criptoativo</b> é toda a representação digital de valor ou de direitos que possa ser transferida ou armazenada eletronicamente com tecnologia de registo distribuído (o guia da AT deixa de fora os NFT).'},
    {t:'h',id:'h1',x:'Três categorias, consoante o que fazes'},
    {t:'ul',id:'u0',x:[
      '<b>Categoria B</b> (rendimentos empresariais e profissionais): atividades ligadas a criptoativos, incluindo a mineração.',
      '<b>Categoria E</b> (capitais): formas de remuneração de operações com criptoativos, como o <i>staking</i>. Tributação a 28%, sem retenção na fonte, com opção de englobamento. Se o rendimento vem em criptoativos, só é tributado quando houver alienação em dinheiro ou em espécie (exceto criptoativos).',
      '<b>Categoria G</b> (mais-valias): a venda de criptoativos com ganho. É o caso que interessa a quem compra e vende como investimento.']},
    {t:'h',id:'h2',x:'Na venda: os 365 dias'},
    {t:'p',id:'p1',x:'Segundo a Autoridade Tributária (guia de outubro de 2023 e artigo 10.º do Código do IRS), os ganhos e perdas da venda de criptoativos que <b>não sejam valores mobiliários</b> não são tributados quando a detenção é igual ou superior a <b>365 dias</b>. Quando é inferior, o ganho é tributado a <b>28%</b> (taxa especial), com opção de englobamento (verificado em 17/11/2026).'},
    {t:'cmp',id:'c1',head:['Tempo de detenção','Tributação','Onde declarar'],rows:[
      ['365 dias ou mais','Fora de tributação','Anexo G1, quadro 7'],
      ['Menos de 365 dias','28% (englobamento opcional; obrigatório se atingires o último escalão)','Anexo G, quadro 18A']],
      cap:'Quadros segundo o folheto da AT sobre criptoativos. Confirma no Modelo 3 do ano.'},
    {t:'p',id:'p2',x:`Conta com números: um ganho de ${_imp_e2(1000)} em criptomoedas detidas há 100 dias paga ${_imp_e2(1000*0.28)}. O mesmo ganho, com 400 dias de detenção, paga ${_imp_e2(0)}. A diferença de prazo vale, no exemplo, ${_imp_e2(280)}.`},
    {t:'h',id:'h3',x:'Trocar cripto por cripto não é vender'},
    {t:'p',id:'p3',x:`Segundo o artigo 10.º do Código do IRS e o guia da AT, se a contrapartida de uma venda é outro criptoativo, não há tributação nesse momento: atribui-se aos criptoativos recebidos o valor de aquisição dos entregues. O imposto só surge quando houver venda em dinheiro (euros) ou em espécie (exceto criptoativos). Exemplo (valores de exemplo): compras uma cripto A por ${_imp_e2(1000)}; mais tarde trocas por uma cripto B que vale ${_imp_e2(3000)} nesse dia: nada a declarar. Depois vendes a B por ${_imp_e2(3500)}. O ganho é ${_imp_e2(3500-1000)}, calculado a partir dos ${_imp_e2(1000)} iniciais, não dos ${_imp_e2(3000)}. Se estiver abaixo de 365 dias, paga ${_imp_e2((3500-1000)*0.28)}.`},
    {t:'note',id:'n0',pending:true,x:'Não ficou confirmado em fonte oficial como se contam os 365 dias quando há trocas sucessivas de cripto por cripto (se conta a data do ativo original ou a da última troca). Antes de vender, confirma com a AT ou com um contabilista.'},
    {t:'h',id:'h4',x:'O cálculo e as regras de prova'},
    {t:'ul',id:'u1',x:[
      'O ganho é a diferença entre o <b>valor de realização</b> (o valor de mercado à data da venda) e o valor de aquisição, podendo deduzir as despesas necessárias e efetivamente suportadas na compra e na venda.',
      'Para valores idênticos, o Código do IRS (artigo 43.º) manda considerar vendidos primeiro os adquiridos há mais tempo, e aplica-se separadamente em cada plataforma onde tens os criptoativos.',
      'A perda da residência fiscal em Portugal equipara-se a uma venda.',
      'A isenção por 365 dias não se aplica quando os rendimentos são auferidos ou devidos por entidades não residentes em países da UE/EEE ou em países com convenção ou acordo de troca de informações fiscais com Portugal (nota do guia da AT).',
      'Os criptoativos que sejam <b>valores mobiliários</b> seguem outro regime: são tributados na venda a 28%, com englobamento obrigatório se detidos menos de 365 dias e o rendimento atingir o último escalão.']},
    {t:'note',id:'n1',pending:true,x:'As indicações dos quadros do Modelo 3 (quadro 7 do Anexo G1 e quadro 18A do Anexo G) vêm de informação da AT de 2023 a 2025. Verifica se houve alterações para o ano em que vendes, e considera falar com um contabilista.'},
    {t:'h',id:'h5',x:'Um caso real: a queda da FTX e o fim de 2022'},
    {t:'p',id:'p4',x:'Em novembro de 2022, a plataforma de criptoativos FTX entrou em colapso e muitos clientes ficaram sem acesso aos fundos. Poucas semanas depois, a Lei n.º 24-D/2022 trouxe as regras fiscais portuguesas sobre criptoativos. Os dois factos contam duas lições diferentes. A fiscal: o tempo que tens os ativos importa (365 dias). A de risco: deixar criptoativos numa plataforma pode ser um risco de contraparte, e o Fundo de Garantia de Depósitos protege depósitos bancários, não criptoativos.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que trocar uma cripto por outra gera sempre imposto (não gera, se a contrapartida for outro criptoativo), ou que nunca gera (gera se converteres em euros).',
      'Esquecer de guardar o histórico de operações de todas as plataformas: sem ele, não calculas o valor de aquisição nem o prazo.',
      'Contar mal os 365 dias e vender «mesmo antes».',
      'Não declarar ganhos de menos de 365 dias por pensar que cripto «não paga imposto».',
      'Ignorar que o <i>staking</i> e a mineração têm tratamento diferente das vendas.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p5',x:'A regra aplica-se a residentes fiscais em Portugal, qualquer que seja a plataforma. A declaração faz-se no Anexo G ou G1, e o cálculo (valor de aquisição, valor de mercado na venda, datas) é teu. Quem usa criptoativos para investir deve tratar o risco como o de um ativo muito volátil, sem rede de proteção de depósitos.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Venda com menos de 365 dias: 28% sobre o ganho, com opção de englobar.',
      'Venda com 365 dias ou mais: ganho fora de tributação (Anexo G1).',
      'Cripto por cripto não gera imposto: o valor de aquisição passa para o ativo recebido.',
      'Staking e mineração seguem outras categorias (E e B).',
      'Guarda o histórico de todas as plataformas: valor de mercado, datas e despesas.']},
    {t:'fazve',id:'q1',ensina:['p1','c1','p2'],q:'Vendeste criptomoedas que tinhas há 100 dias, com um ganho de 1 000 €. Quanto pagas à taxa de 28%?',unit:'€',answer:280,tol:.01,why:'Detidas há menos de 365 dias, o ganho é tributado a 28%: 280 €.'},
    {t:'decide',id:'q2',ensina:['p1','c1'],label:'Decide',q:'Compraste Bitcoin há 400 dias e vendeste com lucro. Segundo a regra, qual é o tratamento fiscal?',o:['Pagas 28% do ganho','Pagas 10%','O ganho fica fora de tributação, por teres detido 365 dias ou mais'],c:2,why:'A detenção igual ou superior a 365 dias exclui o ganho de tributação, no regime descrito pela AT.'},
    {t:'fazve',id:'q3',ensina:['p3'],q:'Compras uma cripto A por 1 000 €, trocas por uma B que vale 3 000 €, e vendes a B por 3 500 € (tudo com menos de 365 dias). Quanto imposto pagas à taxa de 28%, sabendo que o valor de aquisição se mantém nos 1 000 €?',unit:'€',answer:(3500-1000)*0.28,tol:.01,why:`A troca não é tributada. O ganho é 3 500 − 1 000 = 2 500 €. 28% de 2 500 € = ${_imp_e2((3500-1000)*0.28)}.`},
    {t:'erro',id:'q4',ensina:['p3','u1'],label:'Encontra o erro',q:'Um amigo diz: «Troquei bitcoin por outra moeda e já tenho de pagar imposto sobre o ganho dessa troca.» Onde está o erro?',o:['Não há erro','Trocar cripto por cripto não gera tributação; só a conversão em euros (ou em espécie) pode gerar','As trocas pagam 365% de imposto'],c:1,why:'Segundo a AT, enquanto a contrapartida for outro criptoativo, não há tributação nesse momento. Atribui-se ao novo criptoativo o valor de aquisição do entregue.'}
  ], src:[{l:'Portal das Finanças: Criptoativos, conceito fiscal e tributação',u:'https://info.portaldasfinancas.gov.pt/pt/apoio_contribuinte/Folhetos_informativos/Documents/Criptoativos.pdf'},_AT_GUIA,_imp_10,_imp_43] }

);
